// Üretilen dosya: tool/ozgun/uret.py. Müzik · Batı müziği tarihi: besteciler ve dönemler (orta).
const ozMusic1Orta = <(String, String, List<String>, String)>[
  ('Orta Çağ eğitimindeki \'quadrivium\' adlı dört bilim grubunda müzik hangi derslerle birlikte yer alıyordu?', 'Aritmetik, geometri ve astronomi', ['Retorik, mantık ve dil bilgisi', 'Tıp, hukuk, ilahiyat ve felsefe bilimleri', 'Şiir, tarih ve felsefe'], 'Quadrivium sayıya dayalı dört bilimi kapsıyordu; müzik de oranlarla ilgilendiği için aritmetik, geometri ve astronomiyle aynı grupta görülüyordu.'),
  ('Orta Çağ düşünürleri müziği neden quadrivium içinde, yani matematiksel bilimler arasında sınıflandırmıştır?', 'Aralıkları sayısal oranlarla açıklanabilen bir düzen olarak gördükleri için', ['Müziği yalnızca eğlence aracı saydıkları için', 'Kilisenin müziği yasakladığını kanıtlamak için', 'Müziğin hiçbir kuralı ve düzeni olmayan bir doğaçlama olduğunu düşündükleri için'], 'Pisagor geleneğinden gelen anlayışa göre müzik, sayıların sesteki görünümüydü; bu nedenle aritmetik ve geometriyle aynı grupta incelendi.'),
  ('Doğu Roma (Bizans) kilisesinin ayin müziği geleneği ile Batı\'daki Gregoryen ilahi arasındaki temel ortak nokta nedir?', 'İkisinin de esas olarak tek sesli vokal müzik olması', ['İkisinin de piyano eşliğinde söylenmesi', 'İkisinin de Almanca sözlerle yazılması', 'İkisinin de opera sahnesinde ve saray tiyatrolarında doğmuş olması'], 'Bizans ilahileri de Gregoryen ilahi gibi tek sesli, sözü ön plana çıkaran vokal bir müzikti; farklılıklar dilde ve makam sisteminde ortaya çıkıyordu.'),
  ('Bir öğrenci \'Orta Çağ Batı müziği tarihini\' anlatırken başlangıç noktası olarak hangi tür kaynağa en çok dayanmak zorundadır?', 'Kiliselerin elyazmalarında korunmuş ilahilere', ['Ses kayıtlarına ve plaklara', 'Saray orkestralarının basılı partisyonlarına ve programlarına', 'Halk şarkılarının basılı albümlerine'], 'Orta Çağ\'ın erken dönemlerinden kalan müzik belgelerinin büyük çoğunluğu, manastır ve katedrallerde kopyalanan dinî elyazmalarıdır.'),
  ('Gregoryen ilahide her heceye çok sayıda nota düşen süslü yazım biçimine ne ad verilir?', 'Melizmatik', ['Silabik', 'Resitatif', 'Homofonik yazım'], 'Melizmatik ilahide tek bir hece uzun bir nota dizisine yayılır; her heceye bir nota düştüğünde ise silabik yazımdan söz edilir.'),
  ('Orta Çağ\'da kıyamet gününü anlatan ve sonradan pek çok requiemde yer alan ünlü sekans hangisidir?', 'Dies irae', ['Ave Maria', 'Salve Regina', 'Veni Creator'], 'Dies irae (\'Gazap günü\') sekansının ezgisi, Berlioz\'un Fantastik Senfonisi gibi sonraki eserlerde ölüm simgesi olarak alıntılanmıştır.'),
  ('İki koro grubunun ilahiyi ya da mezmuru karşılıklı ve dönüşümlü olarak söylediği icra biçimine ne ad verilir?', 'Antifonal söyleyiş', ['Responsoryal (solist ile koro) söyleyiş', 'Melizmatik söyleyiş', 'Paralel organum'], 'Antifonal icrada iki koro karşılıklı söyler; bir solist ile koronun dönüşümlü söylediği biçime ise responsoryal icra denir.'),
  ('Gregoryen ilahilerin ilk yazılı biçimlerinde ezginin yükselip alçaldığını sözlerin üzerine konan işaretlerle gösteren yazıya ne ad verilir?', 'Neuma yazısı', ['Tablatür', 'Rakamlı bas', 'Kromatik yazı'], 'Neumalar başlangıçta kesin perdeyi değil, ezginin yönünü hatırlatan işaretlerdi; şarkıcı ezgiyi zaten ezbere biliyordu.'),
  ('Neuma yazısının perdeleri kesin göstermemesi, Orta Çağ\'da müziğin aktarımı hakkında ne söyler?', 'Ezgilerin büyük ölçüde sözlü gelenek ve ezberle aktarıldığını', ['Müziğin yalnızca çalgılarla icra edildiğini', 'Bestecilerin her eseri basılı olarak dağıttığını', 'Şarkıcıların ezgiyi her ayinde baştan sona tamamen doğaçladığını'], 'Neumalar bir hafıza destekçisiydi; ezgiyi bilen bir şarkıcıya yön gösteriyor, ama ezgiyi baştan öğretmeye yetmiyordu.'),
  ('Müzik basımının 16. yüzyılda yaygınlaşmasının besteciler açısından en önemli sonucu hangisi olmuştur?', 'Eserlerin farklı ülkelerde aynı biçimde çalınıp tanınabilmesi', ['Bestecilerin artık nota yazmayı bırakması', 'Kilise müziğinin tüm Avrupa\'da kalıcı olarak yasaklanması', 'Çalgıların yapımının sona ermesi'], 'Basım, el kopyalarındaki farklılıkları azalttı; bir bestecinin eserleri kısa sürede Avrupa\'nın birçok kentinde satılır hale geldi.'),
  ('13. yüzyıla ait, öğrenci ve gezgin din adamlarının yazdığı Latince ve Almanca şiirleri içeren ve 20. yüzyılda Carl Orff\'un esinlendiği elyazması derleme hangisidir?', 'Carmina Burana', ['Codex Calixtinus', 'Llibre Vermell', 'Roman de Fauvel'], 'Benediktbeuern manastırında bulunan bu derlemedeki şiirler, Orff\'un 1937\'de seslendirilen ünlü kantatına temel olmuştur.'),
  ('Pérotin\'in Léonin\'den farklı olarak organumu genişlettiği başlıca yön nedir?', 'Üç ve dört sesli organumlar bestelemesi', ['Organumu tamamen çalgılara uyarlaması', 'Latince yerine Fransızca sözler kullanması', 'Tek sesli ilahiye geri dönmesi'], 'Léonin\'in eserleri çoğunlukla iki seslidir; Pérotin ise \'Viderunt omnes\' gibi dört sesli organumlarıyla dokuyu belirgin biçimde zenginleştirmiştir.'),
  ('13. yüzyılda organumdan doğan ve üst seslere ayrı sözler eklenmesiyle oluşan çok sesli türün adı nedir?', 'Motet', ['Opera', 'Fügü', 'Konçerto'], 'Motet, Fransızca \'mot\' (söz) kelimesiyle ilişkilendirilir; üst seslere eklenen sözler bazen farklı dillerde ve farklı konularda olabiliyordu.'),
  ('13. yüzyıl motetlerinde üst seslerin aynı anda farklı metinler, hatta farklı dillerde sözler söylemesi dinleyici açısından hangi sonucu doğurur?', 'Sözlerin tek tek anlaşılmasını güçleştirir', ['Eseri tek sesli bir ilahiye dönüştürür', 'Ritmin tamamen ortadan kalkmasına yol açar', 'Eserin yalnızca çalgılarla çalınmasını zorunlu kılar'], 'Birden fazla metnin üst üste söylenmesi, sözlerden çok ses dokusunu öne çıkarır; bu, sonraki dönemde Karşı Reform eleştirilerinin de konusu olacaktır.'),
  ('14. yüzyılda Fransa\'da ortaya çıkan ve yeni ritim olanaklarını savunan müzik akımı, Philippe de Vitry\'ye atfedilen bir incelemenin adını taşır. Bu ad nedir?', 'Ars Nova', ['Ars Antiqua', 'Ars Subtilior', 'Musica Reservata'], 'Ars Nova (\'yeni sanat\'), önceki dönemin müziğini Ars Antiqua (\'eski sanat\') olarak niteleyen ve ikili bölmeyi kabul eden yeni bir anlayışı temsil eder.'),
  ('Bir bestecinin tamamı tek kişi tarafından yazılmış en eski çok sesli missa ordinariumu olarak bilinen \'Messe de Nostre Dame\'ı hangi besteci yazmıştır?', 'Guillaume de Machaut', ['Philippe de Vitry', 'Francesco Landini', 'Léonin'], 'Machaut\'nun 14. yüzyılda bestelediği bu missa, ordinariumun beş bölümünün tek bir besteci tarafından bir bütün olarak bestelendiği bilinen en eski örnektir.'),
  ('Ars Nova ile Ars Antiqua arasındaki farkı en iyi özetleyen ifade hangisidir?', 'Ars Nova ritimde daha fazla çeşitlilik ve ikili bölmeyi kabul etmiştir', ['Ars Nova çok sesliliği reddederek tek sesli Gregoryen ilahiye dönüşü temsil eder', 'Ars Antiqua çalgı müziğini, Ars Nova yalnızca vokal müziği kapsar', 'İkisi de aynı yüzyılda ve aynı ülkede doğmuş eş anlamlı terimlerdir'], 'Ars Antiqua\'da üçlü bölme \'kusursuz\' kabul edilirken Ars Nova ikili bölmeyi de meşru sayarak ritim olanaklarını genişletmiştir.'),
  ('Almanya\'da saray aşkı temalı şarkılar söyleyen ve trubadurların karşılığı sayılan şair-müzisyenler hangi adla bilinir?', 'Minnesänger', ['Meistersinger', 'Jongleur', 'Truver'], '\'Minne\' Almanca\'da saray aşkı anlamına gelir; Walther von der Vogelweide bu geleneğin en ünlü temsilcilerindendir.'),
  ('Minnesänger geleneğinin ardından 15–16. yüzyıllarda Alman kentlerinde zanaatkârların loncalar içinde kurallı şarkı yarışmaları düzenlediği gelenek hangisidir?', 'Meistersinger', ['Trubadur', 'Goliard', 'Jongleur geleneği'], 'Meistersinger\'ler kentli zanaatkârlardı; Nürnberg\'li ayakkabıcı Hans Sachs bu geleneğin en tanınan adıdır.'),
  ('Trubadurlar ile jonglörler arasındaki temel fark nedir?', 'Trubadurlar şiir ve ezgiyi yaratırken jonglörler çoğunlukla icracıydı', ['Jonglörler yalnızca Latince ilahiler söylerdi', 'Trubadurlar hiçbir zaman şarkı söylemezdi', 'Jonglörler yalnızca manastırlarda yaşar ve dinî ilahiler dışında bir şey söylemezdi'], 'Jonglörler gezgin eğlendiricilerdi; şarkı söyler, çalgı çalar, akrobasi yapardı. Trubadurlar ise eserlerin yaratıcısıydı ve çoğu zaman soyluydu.'),
  ('Richard Wagner\'in, Nürnberg\'li zanaatkâr şarkıcıların yarışmasını konu alan komik operası hangisidir?', 'Die Meistersinger von Nürnberg', ['Tannhäuser und der Sängerkrieg auf Wartburg', 'Lohengrin', 'Parsifal'], 'Wagner bu operada Hans Sachs\'ı başlıca karakterlerden biri yapmış, Alman kentli müzik geleneğini sahneye taşımıştır.'),
  ('15. yüzyıl başında üçlü ve altılı aralıklara dayanan tatlı tınısıyla kıta Avrupası bestecilerini etkileyen İngiliz besteci kimdir?', 'John Dunstable', ['Thomas Tallis', 'William Byrd', 'Henry Purcell'], 'Martin le Franc\'ın şiirinde anılan \'contenance angloise\' (İngiliz tarzı), Dunstable\'ın Burgonya bestecileri üzerindeki etkisini ifade eder.'),
  ('15. yüzyıl missalarında tüm bölümlerin aynı önceden var olan ezgiyi temel alması \'cantus firmus missası\' olarak anılır. Bu tekniğin besteciye sağladığı başlıca yarar nedir?', 'Bölümler arasında birlik ve bütünlük sağlaması', ['Eserin kısa sürede bitmesini sağlaması', 'Sözlerin tamamen çıkarılmasına ve eserin çalgılarla çalınmasına olanak tanıması', 'Koro yerine orkestra kullanmayı gerektirmesi'], 'Ortak bir ezgi tüm bölümleri birbirine bağlayarak missayı bir bütün olarak algılanan çok bölümlü bir esere dönüştürmüştür.'),
  ('Rönesans müziğini Orta Çağ müziğinden ayıran özelliklerden biri hangisidir?', 'Seslerin daha eşit önemde olduğu taklitli çok seslilik', ['Tek sesli ilahiye tamamen dönülmesi', 'Elektronik ve mekanik çalgıların yaygın biçimde kullanılmaya başlanması', 'Sözlerin bütünüyle terk edilmesi'], 'Rönesans\'ta sesler arasında motiflerin sırayla taklit edilmesi yaygınlaştı; böylece bütün sesler dokuya eşit katkı veren bir yapı oluştu.'),
  ('Çağdaşlarınca dönemin en büyük bestecisi sayılan ve Martin Luther\'in \'notaların efendisi\' diye övdüğü Rönesans bestecisi kimdir?', 'Josquin des Prez', ['Orlando di Lasso', 'Giovanni Palestrina', 'Thomas Tallis'], 'Luther, Josquin için \'Diğer besteciler notaların istediğini yapar; Josquin ise notalara istediğini yaptırır\' demiştir.'),
  ('Josquin des Prez\'in \'Ave Maria... virgo serena\' motetinde seslerin birbirini sırayla taklit ederek girmesi hangi Rönesans tekniğine örnektir?', 'Taklitli kontrpuan', ['Rakamlı bas ve sürekli eşlik', 'Monodi', 'Resitatif'], 'Taklitli yazıda bir ses bir motifi sunar, diğerleri aynı motifi farklı perdelerden sırayla tekrarlar; bu teknik Josquin\'de doruğa ulaşmıştır.'),
  ('Bugünkü Belçika, Hollanda ve Kuzey Fransa bölgesinden yetişen ve 15–16. yüzyılda Avrupa saraylarında çalışan bestecilere topluca ne ad verilir?', 'Franko-Flaman okulu', ['Venedik çok korolu okulu', 'Roma okulu', 'Napoli okulu'], 'Dufay, Ockeghem, Josquin ve Lasso gibi Franko-Flaman besteciler, İtalya\'dan Bavyera\'ya kadar birçok sarayda görev yaparak ortak bir müzik dilini yaydı.'),
  ('Bir efsaneye göre çok sesli müziği kiliseden çıkarılmaktan \'kurtaran\' Palestrina missası hangisidir?', 'Missa Papae Marcelli', ['Missa L\'homme armé', 'Missa Pange lingua', 'Missa Ave maris stella'], 'Efsane abartılı olsa da Papa Marcellus Missası, metnin açıkça duyulduğu çok sesli yazının örneği olarak gösterilmiştir.'),
  ('Trento Konsili\'nin çok sesli kilise müziğine yönelttiği temel kaygı aşağıdakilerden hangisidir?', 'Karmaşık dokunun kutsal metni anlaşılmaz kılması', ['Eserlerin fazla kısa olması', 'Korolarda çok az şarkıcı bulunması', 'Kilise bestecilerinin yeterince ücret alamaması ve işten ayrılması'], 'Konsil, dünyevi ezgilerin ve sözü boğan yoğun kontrpuanın ibadetin ciddiyetini bozduğunu düşünüyordu.'),
  ('Rönesans\'ta İngiltere\'de 40 bağımsız ses için yazılmış \'Spem in alium\' motetinin bestecisi kimdir?', 'Thomas Tallis', ['William Byrd', 'John Dowland', 'Orlando Gibbons'], 'Tallis\'in bu motedi sekiz adet beş sesli koro için yazılmıştır ve Rönesans çok sesliliğinin en iddialı örneklerinden biridir.'),
  ('Martin Luther\'e atfedilen ve \'Kudretli bir kaledir Tanrımız\' anlamına gelen ünlü koral hangisidir?', 'Ein feste Burg ist unser Gott', ['Wachet auf, ruft uns die Stimme', 'Nun komm, der Heiden Heiland', 'Jesu, meine Freude, meine Zier'], 'Ein feste Burg Reform\'un simgesi haline gelmiş; Bach bir kantatında, Mendelssohn ise \'Reform\' senfonisinde bu koralı kullanmıştır.'),
  ('Luther\'in Almanca koral geleneğinin 18. yüzyıl Alman müziğine en belirgin katkısı ne olmuştur?', 'Bach\'ın kantat ve pasyonlarında koralların temel malzeme olması', ['Alman operasının tamamen yasaklanması', 'Senfoni türünün doğrudan koral içinden çıkması ve kiliseye taşınması', 'Org müziğinin kiliselerden kaldırılması'], 'Bach, kantatlarını çoğunlukla bir koralla bitirmiş, koral ezgilerini org prelüdlerinde de işlemiştir.'),
  ('Bir madrigalde \'yükseliyor\' sözünde ezginin tırmanması, \'ölüm\' sözünde ise sert bir uyumsuzluk duyulması hangi tekniğe örnektir?', 'Söz resmi', ['İzoritim', 'Basso continuo', 'Cantus firmus tekniği'], 'Söz resminde besteci sözcüğün anlamını ses yüksekliği, ritim ya da uyum yoluyla somutlaştırır; madrigalciler bunu yoğun biçimde kullanmıştır.'),
  ('Napoli yakınlarındaki Venosa Prensi olan, şaşırtıcı kromatik madrigalleriyle ve karısını öldürmesiyle tanınan besteci kimdir?', 'Carlo Gesualdo', ['Luca Marenzio', 'Cipriano de Rore', 'Claudio Monteverdi'], 'Gesualdo\'nun madrigallerindeki beklenmedik kromatik geçişler, kendi döneminin çok ötesinde bulunan bir uyum dili olarak değerlendirilir.'),
  ('Kederli lavta şarkılarıyla tanınan ve \'Flow, my tears\' (Akın gözyaşlarım) adlı eserin bestecisi olan Elizabeth dönemi müzisyeni kimdir?', 'John Dowland', ['Thomas Weelkes', 'William Byrd', 'Thomas Campion'], 'Dowland\'ın melankolik şarkıları, Rönesans İngiltere\'sinde lavta eşlikli şarkı türünün doruk noktası sayılır.'),
  ('16. yüzyıl Fransa\'sında Clément Janequin\'in \'La guerre\' gibi eserlerinde savaş seslerini taklit ettiği çok sesli dünyevi şarkı türü hangisidir?', 'Şanson', ['Madrigal', 'Lied', 'Frottola'], 'Fransız şansonu, Janequin\'in betimleyici eserlerinde kuş cıvıltıları ya da savaş gürültüsü gibi sesleri seslerle taklit eder.'),
  ('Madrigal genellikle nasıl icra edilirdi?', 'Her partiye bir şarkıcı düşen küçük bir topluluk tarafından', ['Yüzlerce kişilik bir kilise korosu tarafından', 'Büyük bir senfoni orkestrası ve kilise orgunun eşliğinde, geniş bir salonda', 'Tek bir solist ve piyano tarafından'], 'Madrigal, eğitimli amatörlerin ve saray müzisyenlerinin evlerde ve saraylarda, her ses partisini bir kişinin söylediği bir oda müziğiydi.'),
  ('Venedik\'teki San Marco Bazilikası\'nın karşılıklı balkonlarına yerleştirilen korolarla oluşturulan çok korolu yazı hangi bestecilerle özdeşleşmiştir?', 'Andrea ve Giovanni Gabrieli', ['Léonin ve Pérotin', 'Jacopo Peri ve Giulio Caccini', 'Lully ve Rameau'], 'Gabrieli\'ler, San Marco\'nun mimarisinden yararlanarak karşılıklı konumlanan korolarla etkileyici ses yankıları yaratmıştır.'),
  ('Venedik okulunun çok korolu müziğinde iki koronun karşılıklı söylemesi dinleyiciye nasıl bir etki bırakır?', 'Sesin mekânda yer değiştirdiği bir stereo etkisi', ['Tüm seslerin tek bir noktadan ve aynı yükseklikten geldiği izlenimi', 'Müziğin tamamen sessizleştiği bir boşluk', 'Sözlerin tümüyle anlaşılmaz hale gelmesi'], 'Cori spezzati (\'bölünmüş korolar\') uygulamasında ses bir balkondan diğerine geçerek mekânsal bir yankı ve karşılıklı konuşma etkisi yaratır.'),
  ('16. yüzyıl sonunda Floransa\'da Antik Yunan dramasının müzikli canlandırılışını yeniden yaratmaya çalışan aydınlar ve müzisyenler topluluğu hangi adla bilinir?', 'Floransa Camerata\'sı', ['Medici Akademisi', 'Venedik okulu', 'Roma Arcadia Akademisi'], 'Kont Giovanni de\' Bardi\'nin evinde toplanan Camerata, sözü ön plana çıkaran tek sesli şarkı (monodi) fikrini geliştirerek operanın doğuşuna zemin hazırlamıştır.'),
  ('Günümüze ulaşan en eski opera kabul edilen ve 1600\'de Floransa\'da sahnelenen \'Euridice\' hangi besteciye aittir?', 'Jacopo Peri', ['Claudio Monteverdi', 'Francesco Cavalli', 'Alessandro Scarlatti'], 'Peri\'nin \'Euridice\'i, IV. Henri ile Maria de\' Medici\'nin düğün törenleri sırasında sahnelenmiştir. Peri\'nin daha önceki \'Dafne\'si büyük ölçüde kayıptır.'),
  ('Operanın doğuşunda Camerata\'nın savunduğu \'monodi\' nedir?', 'Tek bir sesin, basit bir çalgı eşliğiyle sözü öne çıkararak söylediği şarkı', ['Birçok sesin eşit önemde ve taklitli olarak ilerlediği çok sesli koro yazısı', 'Sözsüz ve tamamen çalgılarla çalınan dans müziği', 'Bir ezginin yalnızca çalgılarla kanon halinde çalınması'], 'Camerata, çok sesli yazının sözleri anlaşılmaz kıldığını düşünerek, tek bir sesin sözü açıkça ileten şarkısını Antik Yunan idealine daha yakın bulmuştur.'),
  ('Bir dinleyici, klavsenin sürekli akorlarla eşlik ettiği, bir solist keman ile yaylılar topluluğunun karşılıklı çaldığı bir eser duyuyor. Bu eser büyük olasılıkla hangi döneme aittir?', 'Barok', ['Orta Çağ', 'Empresyonizm', 'Minimalizm'], 'Klavsenli continuo eşliği ve solist–topluluk karşıtlığına dayanan konçerto yapısı Barok dönemin tipik özellikleridir.'),
  ('Vivaldi uzun yıllar Venedik\'te hangi kurumda keman öğretmeni ve müzik yöneticisi olarak çalışmıştır?', 'Ospedale della Pietà', ['San Marco Bazilikası', 'Teatro alla Scala', 'Napoli Konservatuvarı'], 'Pietà, kimsesiz kızların yetiştirildiği bir kurumdu; buradaki kız orkestrası Vivaldi\'nin birçok konçertosunu ilk kez seslendirmiştir.'),
  ('Vivaldi\'nin \'Dört Mevsim\' konçertolarının yayımlanırken her birine sonelerin eşlik etmesi, eseri hangi türün öncülerinden biri yapar?', 'Program müziği', ['Seri müzik', 'Mutlak müzik', 'Minimal ve tekrarlı müzik'], 'Sonelerde anlatılan kuş sesleri, fırtınalar ve uyuyan çoban gibi sahneler müzikte doğrudan betimlenir; bu, müzik dışı bir öyküye dayanan program müziğinin erken bir örneğidir.'),
  ('Bach\'ın Brandenburg Konçertoları adını neden alır?', 'Brandenburg Uçbeyi Christian Ludwig\'e ithaf edildikleri için', ['Brandenburg kentinde bestelendikleri için', 'Berlin\'deki Brandenburg Kapısı\'nın görkemli açılış töreni için yazıldıkları için', 'Bach\'ın doğduğu kentin adı olduğu için'], 'Bach 1721\'de altı konçertodan oluşan bu derlemeyi Brandenburg Uçbeyi Christian Ludwig\'e özenli bir elyazmasıyla sunmuştur.'),
  ('Bach\'ın Matta İncili\'ndeki çarmıha geriliş öyküsünü solistler, iki koro ve iki orkestra için işlediği büyük eser hangisidir?', 'Matthäus-Passion', ['Johannes-Passion', 'Weihnachtsoratorium', 'Messe in h-Moll'], 'Matta Pasyonu ilk kez 1727 civarında Leipzig\'de seslendirilmiş; 1829\'da Mendelssohn\'un yönettiği seslendirme Bach\'a ilginin yeniden canlanmasını başlatmıştır.'),
  ('Bach\'ın ölümünden sonra tamamlanamamış haliyle kalan ve tek bir tema üzerine kurulmuş füg ve kanonlardan oluşan eser hangisidir?', 'Füg Sanatı', ['Musikalisches Opfer', 'Goldberg Varyasyonları', 'İtalyan Konçertosu'], 'Füg Sanatı\'nın son füğü yarım kalmış; bu füğde Bach adının harflerine karşılık gelen B-A-C-H motifi de işlenmiştir.'),
  ('Bach\'ın \'Kahve Kantatı\' gibi eserleri, kantat türü hakkında ne gösterir?', 'Kantatın dünyevi ve mizahi konuları da işleyebildiğini', ['Kantatın yalnızca kilisede söylenebildiğini', 'Kantatların her zaman sözsüz çalgı eserleri olarak yazılıp çalındığını', 'Bach\'ın yalnızca opera bestelediğini'], 'Kahve Kantatı, kahve tutkunu bir kızla babasının çatışmasını anlatan esprili bir dünyevi kantattır ve Leipzig\'deki bir kahvehanede seslendirilmiştir.'),
  ('Händel ile Bach\'ın yaşamları karşılaştırıldığında hangisi doğrudur?', 'İkisi de 1685\'te doğmuş ama hiç karşılaşmamıştır', ['İkisi Leipzig\'de birlikte çalışmıştır', 'Händel, Bach\'ın Leipzig\'deki öğretmeni ve kantor yardımcısıydı', 'İkisi de hayatı boyunca yalnızca opera yazmıştır'], 'İki besteci aynı yıl birbirine yakın kentlerde doğmuş, ancak Bach\'ın Händel\'le görüşme girişimleri sonuçsuz kalmıştır.'),
  ('Händel\'in 1749\'da Aix-la-Chapelle Barışı\'nın kutlanması için yazdığı açık hava müziği hangisidir?', 'Kraliyet Havai Fişek Müziği', ['Su Müziği süitleri', 'Zadok the Priest', 'Messiah\'ın Hallelujah korosu'], 'Eserin Green Park\'taki ilk büyük seslendirmesi sırasında havai fişek yapısının bir bölümü alev almıştır.'),
  ('XIV. Louis\'nin sarayında müziğin başında bulunan, İtalyan kökenli olup Fransız operasının (tragédie lyrique) kurucusu sayılan besteci kimdir?', 'Jean-Baptiste Lully', ['Jean-Philippe Rameau', 'François Couperin', 'Marc-Antoine Charpentier de Paris'], 'Floransa doğumlu Lully, Fransızcanın vurgularına uygun resitatif ve bale ağırlıklı yapısıyla Fransız operasının kalıplarını belirlemiştir.'),
  ('Jean-Baptiste Lully\'nin ölümüne yol açan olay nedir?', 'Asasıyla ayağını yaralaması ve yaranın kangrene dönmesi', ['Bir düelloda yaralanması', 'Saray yangınında kalması', 'Bir at arabası kazası geçirmesi'], 'Lully 1687\'de bir Te Deum\'u yönetirken yere vurarak tempo tuttuğu asayı ayağına çarpmış, kangren olan yarayı kestirmeyi reddedince ölmüştür.'),
  ('\'Traité de l\'harmonie\' (1722) adlı incelemesiyle uyum kuramının temellerini atan ve operalarıyla da tanınan Fransız besteci kimdir?', 'Jean-Philippe Rameau', ['Jean-Baptiste Lully', 'François Couperin le Grand', 'Marin Marais'], 'Rameau\'nun incelemesi akorların temel ses üzerinden çözümlenmesini sistemleştirmiş, sonraki uyum öğretimini derinden etkilemiştir.'),
  ('Fransız Baroku\'nda opera ile bale arasındaki ilişki için hangisi söylenebilir?', 'Dans sahneleri operanın ayrılmaz ve önemli bir parçasıydı', ['Operada dans kesinlikle yasaktı', 'Bale yalnızca İtalya\'da yapılıyordu', 'Opera ile bale hiçbir zaman aynı eserde bir araya gelmezdi'], 'Kralın da bizzat dans ettiği bir saray kültüründe Fransız operası divertissement adı verilen uzun dans bölümleri içerirdi.'),
  ('\'Dido ve Aeneas\'ın sonunda Dido\'nun ölmeden önce söylediği ve tekrarlanan bir bas çizgisi üzerine kurulu ünlü arya hangisidir?', 'Dido\'nun Ağıtı', ['Kraliçe\'nin Gece Aryası', 'Kuğu Şarkısı', 'Habanera'], 'Bu arya, kromatik olarak inen ve sürekli tekrar eden bir bas (ground bass) üzerine kurulmuştur ve Barok ağıtının en ünlü örneklerindendir.'),
  ('Benjamin Britten\'ın \'Gençler İçin Orkestra Rehberi\' adlı eserinde tema olarak kullandığı ezgi hangi besteciye aittir?', 'Henry Purcell', ['Georg Friedrich Händel', 'Edward Elgar', 'Ralph Vaughan Williams'], 'Britten bu eserinde Purcell\'in \'Abdelazer\' sahne müziğinden bir rondoyu tema olarak kullanmış ve orkestranın bölümlerini tanıtmıştır.'),
  ('Arcangelo Corelli Barok müzikte hangi türün örnek eserlerini vermiştir?', 'Keman sonatı ve concerto grosso', ['Opera seria ve opera buffa', 'Org füğü ve koral prelüdü', 'Senfoni ve senfonik şiir'], 'Corelli\'nin Op. 5 keman sonatları ve Op. 6 concerto grosso\'ları yüzyıllarca model alınmış, keman tekniğinin gelişimine yön vermiştir.'),
  ('555 klavsen sonatı besteleyen ve hayatının önemli bir kısmını İspanya ve Portekiz saraylarında geçiren İtalyan besteci kimdir?', 'Domenico Scarlatti', ['Alessandro Scarlatti', 'Giovanni Battista Pergolesi', 'Giuseppe Tartini'], 'Domenico Scarlatti, Portekiz prensesi Maria Barbara\'nın hocası olmuş ve onunla birlikte Madrid\'e gitmiştir; tek bölümlü sonatları klavye tekniğinde çığır açmıştır.'),
  ('Yaşadığı dönemde Bach\'tan çok daha ünlü olan, binlerce eser yazdığı bilinen ve Hamburg\'da müzik yöneticisi olan Barok besteci kimdir?', 'Georg Philipp Telemann', ['Johann Pachelbel', 'Heinrich Schütz', 'Carl Philipp Emanuel Bach'], 'Telemann döneminin en verimli ve en çok aranan bestecilerinden biriydi; Leipzig kantorluğuna önce o seçilmiş, ancak teklifi kabul etmemiştir.'),
  ('Tartini\'ye ait olduğu bilinen ve bestecinin rüyasında şeytanın kemanla çaldığını duyduğu ezgiye dayandığı anlatılan keman sonatı hangisidir?', 'Şeytanın Triller Sonatı', ['Folia Varyasyonları', 'La Campanella', 'Kreutzer Sonatı'], 'Tartini\'nin anlattığına göre rüyasında şeytan kemanı alıp olağanüstü bir sonat çalmıştı; uyanınca bunu hatırlamaya çalışarak eseri yazmıştır.'),
  ('Klasik dönemde Avrupa\'da müzik yaşamındaki önemli bir toplumsal değişim hangisidir?', 'Halka açık konserlerin ve orta sınıf dinleyicinin artması', ['Müziğin yalnızca kilise için yazılmaya başlanması', 'Bestecilerin saraylarla bütün bağlarını bir anda koparması', 'Nota basımının tamamen durması'], '18. yüzyılın ikinci yarısında bilet satılan konserler, amatör müzisyenler için basılan notalar ve kentli dinleyici kitlesi hızla büyümüştür.'),
  ('Aydınlanma çağının \'doğallık ve sadelik\' ideali Klasik dönem müziğine nasıl yansımıştır?', 'Anlaşılır ezgilerin ve dengeli biçimlerin öne çıkması', ['Müziğin olabildiğince karmaşık ve gizemli yazılması', 'Bütün eserlerin Latince sözlerle yazılması', 'Çalgıların yasaklanıp yalnızca koro kullanılması'], 'Aydınlanma düşüncesi akla ve geniş kitlelere seslenmeyi önemsiyordu; bu da açık, dengeli ve \'doğal\' duyulan bir müzik zevkini besledi.'),
  ('18. yüzyılda bir bestecinin genellikle bir soylunun hizmetinde, üniformalı bir çalışan olarak görev yapmasını en iyi gösteren örnek hangisidir?', 'Haydn\'ın Esterházy sarayında kapel ustası olması', ['Beethoven\'ın serbest besteci olarak geçinmesi', 'Liszt\'in Avrupa turnelerine çıkması', 'Wagner\'in kendi tiyatrosunu kurması'], 'Haydn yaklaşık 30 yıl Esterházy prenslerinin hizmetinde çalışmış, sözleşmesi gereği yeni eserler yazıp orkestrayı yönetmiştir.'),
  ('Haydn\'ın 1790\'larda Londra\'ya yaptığı iki seyahatin kariyerindeki önemi nedir?', 'Kamusal konserlerde büyük başarı ve kazanç', ['İlk kez bir sarayın hizmetine girmesi', 'Opera bestelemeyi tümüyle bırakması', 'Mozart ile ilk kez orada tanışması'], 'Empresaryo Johann Peter Salomon\'un davetiyle Londra\'da seslendirilen 12 \'Londra\' senfonisi Haydn\'a uluslararası ün ve önemli bir gelir getirmiştir.'),
  ('Haydn\'ın Londra\'da Händel oratoryolarını dinledikten sonra bestelediği, evrenin yaratılışını anlatan oratoryo hangisidir?', 'Yaratılış (Die Schöpfung)', ['Mevsimler (Die Jahreszeiten)', 'Messiah', 'İsrail Mısır\'da'], 'Yaratılış 1798\'de Viyana\'da seslendirilmiştir; başlangıçtaki \'Kaos\' betimlemesi ve \'Işık olsun\' anındaki güçlü do majör akoruyla ünlüdür.'),
  ('Mozart\'ın eserlerini kronolojik olarak numaralandıran katalog, hazırlayıcısının adıyla nasıl anılır?', 'Köchel (K.) kataloğu', ['Hoboken kataloğu', 'BWV', 'Opus kataloğu'], 'Ludwig von Köchel 1862\'de Mozart\'ın eserlerini sıralamış; bugün eserler \'K. 525\' gibi numaralarla anılır. Hoboken kataloğu Haydn\'a, BWV Bach\'a aittir.'),
  ('Mozart\'ın çocukluğunda babası Leopold\'la birlikte Avrupa saraylarını gezmesi kariyerine nasıl katkıda bulunmuştur?', 'Farklı ülkelerin üsluplarını erkenden tanımasını sağlamıştır', ['Onu müzikten uzaklaştırıp hukuk okumaya yöneltmiştir', 'Yalnızca Alman müziğini tanımasına yol açmıştır', 'Bestecilik yerine yalnızca şarkıcılık yapmasına neden olmuştur'], 'Paris, Londra ve İtalya yolculuklarında Mozart, J. C. Bach gibi bestecilerle tanışmış, İtalyan operası ve senfoni üslubunu yakından öğrenmiştir.'),
  ('Mozart\'ın Lorenzo Da Ponte\'nin libretto yazdığı operalardan biri hangisi değildir?', 'Sihirli Flüt', ['Figaro\'nun Düğünü', 'Don Giovanni', 'Così fan tutte'], 'Da Ponte ile Figaro, Don Giovanni ve Così fan tutte\'yi yazan Mozart\'ın Sihirli Flüt\'ünün librettosu Emanuel Schikaneder\'e aittir.'),
  ('Mozart\'ın Figaro\'nun Düğünü operası, Beaumarchais\'nin bir oyununa dayanır. Bu oyunun dönemi için cesur sayılmasının nedeni nedir?', 'Bir uşağın soylu efendisini alt etmesini anlatması', ['Kiliseyi açıkça övmesi', 'Osmanlı sarayında geçmesi ve padişahı övmesi', 'Bütün karakterlerin tanrılar olması'], 'Oyun, soyluların ayrıcalıklarını eleştirdiği için Viyana\'da yasaklanmıştı; Da Ponte siyasi göndermeleri yumuşatarak operayı sahnelenebilir hale getirmiştir.'),
  ('Mozart\'ın \'Saraydan Kız Kaçırma\' operası ve piyano sonatındaki \'Rondo alla turca\' bölümü 18. yüzyıl Avrupa\'sındaki hangi ilgiyi yansıtır?', 'Osmanlı mehter müziğine ve \'Türk\' temalarına duyulan merak', ['Çin operasına duyulan hayranlık', 'Afrika ve Latin Amerika ritimlerine duyulan ilgi', 'Antik Mısır müziğini canlandırma isteği'], '18. yüzyılda Viyana\'da Osmanlı\'yı çağrıştıran \'alla turca\' üslubu modaydı; büyük davul, zil ve üçgen gibi mehter etkili çalgılar bu etkiyi yaratmak için kullanıldı.'),
  ('Mozart\'ın 1781\'de Salzburg Başpiskoposu\'nun hizmetinden ayrılarak Viyana\'ya yerleşmesi neyin erken bir örneğidir?', 'Saray hizmeti yerine serbest çalışmayı seçmenin', ['Bir bestecinin kiliseye rahip olarak girmesinin', 'Bir bestecinin müziği tümüyle bırakmasının', 'Bir bestecinin devlet memuru olmasının'], 'Mozart Viyana\'da ders vererek, konser düzenleyerek ve eser satarak geçinmeye çalışmıştır; bu, sabit bir saray maaşı olmadan yaşamanın zorluklarını da göstermiştir.'),
  ('Beethoven\'ın kardeşlerine yazdığı ama hiç göndermediği, sağırlığının verdiği umutsuzluğu ve sanatı için yaşama kararını anlatan mektup hangi adla bilinir?', 'Heiligenstadt Vasiyetnamesi', ['Ölümsüz Sevgiliye Mektup', 'Bonn Manifestosu ve Viyana Notları', 'Viyana Bildirgesi'], 'Beethoven bu belgeyi 1802\'de Viyana yakınlarındaki Heiligenstadt\'ta yazmıştır; belge ölümünden sonra bulunmuştur.'),
  ('Beethoven\'ın 3. Senfonisi \'Eroica\'nın ithaf sayfasındaki adı silmesiyle ilgili anlatılan olay nedir?', 'Napolyon\'un kendini imparator ilan ettiğini duyunca ithafı geri alması', ['Hamisi olan prensin ödemeyi aylarca geciktirmesi üzerine ithafı başka birine çevirmesi', 'Eserin ilk seslendirmesinin başarısız olması', 'Haydn\'ın eseri beğenmediğini söylemesi'], 'Öğrencisi Ries\'e göre Beethoven, özgürlüğün simgesi saydığı Napolyon\'un 1804\'te imparator olduğunu duyunca öfkeyle adı silmiştir.'),
  ('Beethoven\'ın 5. Senfonisi\'nin açılışındaki dört notalık motif (üç kısa, bir uzun) eserin bütününde nasıl kullanılır?', 'Sonraki bölümlerde dönüşerek yeniden beliren birleştirici bir öğe olarak', ['Yalnızca ilk ölçüde duyulup bir daha hiç kullanılmaz', 'Her bölümde aynı ses perdesinde, aynı çalgıda ve hiç değişmeden tekrar edilir', 'Yalnızca koro tarafından söylenen bir sözün ezgisidir'], 'Kısa–kısa–kısa–uzun ritmi üçüncü bölümde ve finalde de belirir; tek bir motifin bütün eseri birleştirmesi Beethoven\'ın yeniliklerindendir.'),
  ('Beethoven\'ın 6. Senfonisi \'Pastoral\'in bölümlerine \'Dere kıyısında sahne\' ve \'Fırtına\' gibi adlar vermesi eseri hangi müzik anlayışına yaklaştırır?', 'Program müziği', ['Seri müzik', 'Mutlak müzik', 'Aleatorik müzik'], 'Pastoral Senfoni kırsal yaşamı betimler; Beethoven bunun \'resim yapmaktan çok duygunun ifadesi\' olduğunu belirtse de eser program müziğinin önemli bir öncüsüdür.'),
  ('Beethoven\'ın kariyerinde, Mozart ve Haydn\'dan farklı olarak öne çıkan durum hangisidir?', 'Soylu hamilerin desteğiyle ama bir sarayın hizmetkârı olmadan çalışabilmesi', ['Hayatı boyunca tek bir kilisede orgcu olarak çalışması ve kantor maaşıyla geçinmesi', 'Hiç eser yayımlamaması', 'Yalnızca opera bestelemesi'], 'Prens Lobkowitz, Arşidük Rudolph ve Prens Kinsky 1809\'da Beethoven\'a Viyana\'da kalması için yıllık bir gelir bağlamış, ondan saray görevi beklememiştir.'),
  ('18. yüzyılda opera seria\'daki aşırı süslemelere ve şarkıcı gösterilerine karşı çıkarak dramın sadeliğini savunan opera reformcusu kimdir?', 'Christoph Willibald Gluck', ['Johann Adolf Hasse', 'Alessandro Scarlatti', 'Gioachino Rossini'], 'Gluck \'Orfeo ed Euridice\' (1762) ve \'Alceste\' ile müziği dramın hizmetine sokmayı amaçlayan bir reform başlatmıştır.'),
  ('Gluck\'un \'Alceste\' operasının önsözünde dile getirdiği temel ilke hangisidir?', 'Müziğin şiire ve dramaya hizmet etmesi, gösteriş için durdurulmaması', ['Şarkıcıların her aryada istedikleri kadar süsleme ve kadans ekleyebilmesi', 'Operanın tamamen konuşmalı olması', 'Orkestranın sahneden kaldırılması'], 'Gluck, eylemi bölen uzun da capo aryalarını ve şarkıcıların gösteriş için yaptığı süslemeleri sınırlamayı savunmuştur.'),
  ('Barok ile Klasik arasındaki geçiş döneminde ortaya çıkan, hafif, zarif ve süsleyici bir zevki yansıtan üsluba ne ad verilir?', 'Galant üslup', ['Gotik üslup', 'Empresyonist üslup', 'Seri üslup'], 'Galant üslup, karmaşık kontrpuan yerine kolay anlaşılır ezgiler ve basit eşlikler öne çıkararak Klasik üslubun hazırlayıcısı olmuştur.'),
  ('19. yüzyılda virtüöz solistlerin büyük konser salonlarında hayranlarınca adeta bir yıldız gibi karşılanması müzik yaşamındaki hangi değişimi gösterir?', 'İcracının ünlü bir kamusal figür haline gelmesi', ['Konserlerin yalnızca saraylarda yapılmaya başlanması', 'Bestecilerin anonim kalmayı tercih etmesi', 'Çalgı müziğinin tamamen terk edilmesi'], 'Paganini ve Liszt gibi virtüözler, bilet satılan konserlerde büyük kalabalıkları çekerek modern \'yıldız\' icracı kavramının öncüsü olmuştur.'),
  ('Bir eleştirmen, \'Müzik başka hiçbir şeyi anlatmamalı, yalnızca seslerin biçimiyle değerlendirilmelidir\' diyor. Bu görüş 19. yüzyılda hangi anlayışla özdeşleşmiştir?', 'Mutlak müzik', ['Program müziği', 'Verismo', 'Senfonik şiir'], 'Eleştirmen Eduard Hanslick gibi mutlak müzik savunucuları, Brahms\'ın eserlerini örnek göstererek müziğin anlamının kendi biçiminde olduğunu öne sürmüştür.'),
  ('Schubert\'in Goethe\'nin şiirine bestelediği \'Erlkönig\'de piyanodaki hızlı tekrarlanan notalar neyi betimler?', 'Bir babanın oğluyla birlikte gece at sürüşünü', ['Bir dere kıyısında akan suyu', 'Bir kilisenin çanlarını', 'Ormanda öten kuşları ve rüzgârın sesini'], 'Erlkönig\'de babası ve hasta oğlu dörtnala giderken, Elf Kralı çocuğu çağırır; piyanonun ısrarlı üçlemeleri atın nal seslerini ve gerilimi verir.'),
  ('Schubert\'in \'Erlkönig\'inde tek bir şarkıcının anlatıcı, baba, çocuk ve Elf Kralı\'nı canlandırması hangi beceriyi gerektirir?', 'Sesin rengini ve karakterini her kişiye göre değiştirmeyi', ['Aynı anda iki ezgi söylemeyi', 'Şarkıyı ezbere değil, sahnede nota okuyarak ve oturarak söylemeyi', 'Yalnızca piyanoyla konuşmayı'], 'Schubert her karaktere farklı ses aralığı ve ezgi karakteri vermiştir; şarkıcı bunları tek başına ayırt edilebilir kılmak zorundadır.'),
  ('Schubert\'in \'Alabalık\' adlı beşlisinin bir bölümü, aynı adlı şarkısının ezgisi üzerine yazılmış varyasyonlardır. Bu durum Schubert\'in eserleri hakkında neyi gösterir?', 'Şarkı ile çalgı müziği arasında malzeme alışverişi yaptığını', ['Çalgı müziği yazmayı hiç sevmediğini', 'Yalnızca başkalarının ezgilerini kullandığını', 'Bütün şarkılarını sonradan senfoniye dönüştürmek zorunda olduğunu'], 'Schubert bazı şarkılarının ezgilerini oda müziği eserlerinde yeniden işlemiştir; \'Alabalık\' ve \'Ölüm ve Kız\' dörtlüsü bunun bilinen örnekleridir.'),
  ('Robert Schumann\'ın Chopin\'in bir eserini tanıtırken yazdığı ünlü cümle hangisidir?', '\'Şapkalarınızı çıkarın beyler, bir dahi!\'', ['\'Müzik mimarinin donmuş halidir.\'', '\'Ben bir halk şarkıcısıyım.\'', '\'Tanrı\'ya şükür, Bach öldü.\''], 'Schumann 1831\'de Chopin\'in \'Là ci darem\' varyasyonları hakkında yazdığı yazıda bu sözlerle genç besteciyi müzik dünyasına tanıtmıştır.'),
  ('Robert Schumann\'ın eşi Clara Schumann 19. yüzyıl müzik yaşamında en çok hangi yönüyle tanınmıştır?', 'Avrupa\'nın en saygın konser piyanistlerinden biri olmasıyla', ['Opera şarkıcısı olarak sahneye çıkmasıyla', 'Avrupa\'da büyük bir senfoni orkestrasını yöneten ilk kadın şef olmasıyla', 'Bir konservatuvarın kurucusu olmasıyla'], 'Clara Wieck-Schumann onlarca yıl uluslararası konser veren bir piyanistti, aynı zamanda besteciydi ve Brahms\'ın yakın dostuydu.'),
  ('Robert Schumann\'ın piyanist olarak kariyer yapma hayalinin sona ermesinin nedeni nedir?', 'Elindeki parmak sorununun piyano çalmasını engellemesi', ['Sağırlığının ilerlemesi', 'Bir savaşta yaralanması', 'Babasının müziği yasaklayıp onu hukuk fakültesine yazdırması'], 'Schumann sağ elinin parmaklarında gelişen kalıcı bir sorun yüzünden piyanistliği bırakmış ve kendini besteciliğe ve eleştiriye vermiştir.'),
  ('1829\'da Bach\'ın Matta Pasyonu\'nu Berlin\'de yöneterek Bach\'a yeniden ilgi uyandıran besteci kimdir?', 'Felix Mendelssohn', ['Robert Schumann', 'Franz Liszt', 'Carl Maria von Weber'], 'Mendelssohn 20 yaşında yönettiği bu seslendirmeyle Bach\'ın büyük vokal eserlerinin yeniden keşfedilmesine öncülük etmiştir.'),
  ('Mendelssohn\'un İskoçya\'daki Staffa Adası\'nı ziyaretinden esinlendiği konser uvertürü hangisidir?', 'Hebridler (Fingal Mağarası)', ['Deniz Durgunluğu', 'Peer Gynt süiti (Grieg)', 'Moldau'], 'Mendelssohn 1829\'daki gezisinde Fingal Mağarası\'nı görmüş ve dalgaların hareketini anımsatan bu uvertürü yazmıştır.'),
  ('Mendelssohn\'un 1843\'te kurduğu ve kısa sürede Avrupa\'nın önde gelen müzik okullarından biri olan konservatuvar hangi kenttedir?', 'Leipzig', ['Berlin', 'Münih', 'Hamburg ve Bremen'], 'Mendelssohn aynı kentte Gewandhaus Orkestrası\'nın şefiydi; kurduğu konservatuvar Schumann gibi öğretmenleriyle Avrupa\'nın önemli müzik okullarından biri olmuştur.'),
  ('Felix Mendelssohn\'un ablası Fanny Mendelssohn Hensel\'in birçok eserinin başlangıçta kardeşinin adıyla yayımlanmasının başlıca nedeni nedir?', 'Dönemin toplumsal kurallarının kadınların profesyonel bestecilik yapmasını hoş görmemesi', ['Fanny\'nin nota yazmayı bilmemesi', 'Eserlerinin yalnızca çocuklar için olması', 'Fanny\'nin yayıncısıyla adını gizlemeyi öngören gizli bir sözleşme imzalamış olması ve bunu bozamaması'], 'Babası ve kardeşi müziği Fanny için bir meslek değil, ev içi bir uğraş olarak görüyordu; bazı şarkıları bu yüzden Felix\'in adıyla basıldı.'),
  ('Chopin\'in \'Devrimci\' Etüdü\'nü, Polonya\'daki 1830–1831 ayaklanmasının bastırıldığı haberini aldığı dönemde yazdığı anlatılır. Bu bilgi esere nasıl bir yorum katar?', 'Eserin ulusal bir acıyı ve öfkeyi yansıttığı biçiminde', ['Eserin neşeli bir düğün dansı olduğu biçiminde', 'Eserin kilise ayini için yazıldığı biçiminde', 'Eserin bir çocuk şarkısının uyarlaması olduğu biçiminde'], 'Sol eldeki fırtınalı pasajlar ve dramatik karakter, Varşova\'nın Rus ordusunca alınmasına duyulan öfkeyle ilişkilendirilir.'),
  ('Bir piyanist, gece havası taşıyan, sol elde yumuşak akor eşlikleri ve sağ elde şarkı gibi süslü bir ezgiden oluşan bir Chopin eseri çalıyor. Bu eserin türü büyük olasılıkla hangisidir?', 'Noktürn', ['Polonez', 'Etüt', 'Mazurka'], 'Noktürn (\'gece parçası\') türünü İrlandalı John Field başlatmış, Chopin şarkı gibi akan ezgileriyle türün en ünlü bestecisi olmuştur.'),
  ('Genç Liszt\'in 1832\'de Paganini\'yi dinledikten sonra verdiği karar neydi?', 'Piyanoda Paganini\'ye denk bir virtüözlük geliştirmek', ['Piyanoyu bırakıp keman çalmaya başlamak', 'Konser vermeyi tümüyle bırakmak', 'Yalnızca kilise müziği yazmak'], 'Liszt Paganini\'nin etkisiyle piyano tekniğini yeniden ele almış ve \'Paganini Etütleri\'ni yazmıştır.'),
  ('Liszt\'in piyano resitali (solo konser) uygulamasına katkısı nedir?', 'Tek başına ve ezbere verilen solo resitali yaygınlaştırması', ['Piyanoyu orkestranın içine gizlemesi', 'Konserlerde yalnızca başka piyanistlere çaldırması', 'Piyano konserlerinde notayı zorunlu kılması'], 'Önceleri konserler birçok sanatçının katıldığı karma programlardı; Liszt\'in tek başına verdiği konserler \'resital\' kavramını yerleştirmiştir.'),
  ('Berlioz\'un Fantastik Senfoni\'sinde sevgiliyi temsil eden ve her bölümde dönüşerek yeniden beliren ezgiye ne ad verilir?', 'İdée fixe (sabit fikir)', ['Leitmotiv ağı (dönen motifler)', 'Cantus firmus', 'Ritornello ezgisi'], 'İdée fixe, eserin beş bölümünü birleştirir; son bölümde cadıların ayininde bayağılaştırılmış bir dans ezgisine dönüşür.'),
  ('Fantastik Senfoni\'nin son bölümünde \'Dies irae\' ezgisinin kullanılması hangi amaca yöneliktir?', 'Ölümü çağrıştırarak cadılar ayinini korkutucu kılmak', ['Eserin bir kilise ayininde çalınmasını sağlamak', 'Dinleyicilere tanıdık bir neşeli şarkı sunmak', 'Senfoniyi Gregoryen ilahiye dönüştürmek'], 'Ölüler ayininden alınan bu ezgi, karikatürize edilerek bir cehennem şenliği havası yaratır.'),
  ('Berlioz\'un çok büyük kadrolar kullanma eğilimi en iyi hangi örnekle açıklanır?', 'Requiem\'inde ek olarak dört bakır üflemeli grup kullanması', ['Bütün eserlerini yalnızca solo flüt için yazması', 'Hiçbir zaman vurmalı çalgı kullanmaması', 'Senfonilerini dört kişilik oda topluluklarına yazması'], 'Berlioz\'un \'Grande Messe des morts\'u, salonun köşelerine yerleştirilen dört bakır üflemeli grup ve çok sayıda timpaniyle büyük bir ses etkisi yaratır.'),
  ('Richard Wagner\'in, operada müzik, şiir, sahne ve görsel sanatları tek bir bütünde birleştirme idealine verdiği ad nedir?', 'Gesamtkunstwerk (toplam sanat yapıtı)', ['Bel canto (güzel şarkı)', 'Singspiel (şarkılı oyun)', 'Opera buffa (komik opera)'], 'Wagner, sanatların eşit ve birbirine bağlı biçimde bir araya geldiği bir \'toplam sanat yapıtı\' yaratmayı amaçlamıştır.'),
  ('Wagner\'in dört operadan oluşan büyük eseri \'Der Ring des Nibelungen\' hangi operayla başlar?', 'Das Rheingold', ['Die Walküre', 'Siegfried', 'Götterdämmerung'], 'Döngü Rheingold, Walküre, Siegfried ve Götterdämmerung sırasıyla ilerler; tamamı yaklaşık 15 saat sürer.'),
  ('Wagner\'in operalarında geleneksel olarak birbirinden ayrı duran arya ve resitatif yerine ne kullandığı söylenir?', 'Kesintisiz akan \'sonsuz ezgi\' anlayışı', ['Konuşmalı diyaloglar ve şarkısız sahneler', 'Yalnızca koro bölümleri', 'Ayrı ayrı numaralanmış kısa şarkılar'], 'Wagner\'in olgun eserleri numaralara bölünmez; müzik bir sahneden diğerine kesintisiz akar ve orkestra anlatının taşıyıcısı olur.'),
  ('Wagner\'in eserlerinde librettoyu başka bir yazara bırakmayıp kendisinin yazması, onun hangi idealiyle tutarlıdır?', 'Sözü ve müziği tek bir bütün olarak tasarlama isteği', ['Operayı sözsüz bir çalgı eseri yapma isteği', 'İtalyan şairleriyle çalışmayı reddetme zorunluluğu', 'Operaları Latince yazma isteği'], 'Gesamtkunstwerk anlayışına uygun olarak Wagner hem metni hem müziği hem de sahne tasarımını kendi denetiminde tutmak istemiştir.'),
  ('Verdi\'nin \'Nabucco\' operasındaki \'Va, pensiero\' korosu İtalyanlar için neden özel bir anlam kazanmıştır?', 'Sürgündeki İbranilerin özlemi, İtalyanların duygularına benzetildiği için', ['Korodaki ezgi İtalya\'nın resmî marşı olarak yazıldığı için', 'Papa bu koroyu kilise ilahisi ilan ettiği için', 'Verdi\'nin cenazesinde ilk kez söylendiği için'], '19. yüzyılda bu koro, İtalyan birliği (Risorgimento) dönemindeki ulusal duygularla bağdaştırılmıştır; Verdi\'nin cenazesinde de kalabalık tarafından söylenmiştir.'),
  ('Risorgimento döneminde duvarlara yazılan \'Viva VERDI\' sloganının ikinci bir anlamı nedir?', 'Vittorio Emanuele Re d\'Italia', ['Verdi\'nin bütün operalarının listesi', 'Venedik\'in özgürlük çağrısı', 'Avusturya imparatoruna bağlılık bildirisi'], 'Sloganın harfleri, İtalyan birliğinin simgesi olarak görülen Sardinya Kralı Vittorio Emanuele\'yi gizlice selamlamanın bir yoluydu.'),
  ('Verdi\'nin \'La traviata\' operası, dönemin diğer operalarına göre konusu bakımından neden cesur bulunmuştur?', 'Çağdaş bir kurtizanı başkahraman yapması', ['Mitolojik tanrıları alaya alması', 'Hiç kadın karakter içermemesi', 'Tamamen konuşmalı olması'], 'Dumas\'nın \'Kamelyalı Kadın\'ına dayanan opera, Paris\'in kibar fahişesi Violetta\'yı sempatiyle anlatır; çağdaş konusu nedeniyle sansürle karşılaşmıştır.'),
  ('Verdi\'nin hayatının sonlarına doğru Shakespeare\'in eserlerine dayanarak, şair Arrigo Boito\'yla birlikte yazdığı son iki operası hangileridir?', 'Otello ve Falstaff', ['Macbeth ve Kral Lear operaları', 'Aida ve Don Carlo', 'Nabucco ve Ernani'], 'Verdi \'Otello\'yu 1887\'de, tek önemli komik operası olan \'Falstaff\'ı ise 1893\'te, 79 yaşındayken sahnelemiştir.'),
  ('Rossini\'nin uvertürlerinde sık kullandığı ve bir ezginin her yinelenişinde ses gürlüğünü ve heyecanı adım adım artırdığı teknik hangi adla anılır?', 'Rossini kreşendosu', ['Mannheim roketi ve crescendosu', 'Tristan akoru', 'Alberti bası'], 'Rossini\'nin uvertürlerinde kısa bir ezgi tekrar tekrar çalınırken çalgılar eklenir ve gürlük yükselir; bu etki \'Rossini kreşendosu\' diye anılır.'),
  ('Bir opera izleyicisi, uzun soluklu, ağır ve şarkı gibi akan ezgileriyle \'Casta diva\' aryasını dinliyor. Bu arya hangi besteciye ve operaya aittir?', 'Bellini – Norma', ['Verdi – Aida', 'Puccini – Tosca', 'Mozart – Don Giovanni'], '\'Casta diva\', Bellini\'nin 1831 tarihli \'Norma\' operasında Galyalı rahibe Norma\'nın aya seslendiği ünlü aryadır.'),
  ('Donizetti\'nin \'Lucia di Lammermoor\' operasında başkahramanın aklını yitirdiği sahnenin bel canto geleneğindeki yeri nedir?', 'Sopranodan büyük virtüözlük isteyen bir delilik sahnesi olması', ['Operanın tamamen konuşmalı tek bölümü olması', 'Koronun sahneye hiç çıkmadığı tek bölüm olması', 'Orkestranın sustuğu ve yalnızca dansın sürdüğü bölüm olması'], 'Lucia\'nın delilik sahnesi, flütle diyalog kuran uzun süslemeleriyle bel canto sopranolarının yeteneklerini sergilediği en ünlü sahnelerden biridir.'),
  ('Rossini\'nin Sevil Berberi ile Mozart\'ın Figaro\'nun Düğünü arasındaki ilişki nedir?', 'İkisi de Beaumarchais\'nin Figaro oyunlarına dayanır', ['İkisi de aynı yıl aynı kentte bestelenmiştir', 'Rossini Mozart\'ın operasının ikinci perdesini yeniden yazmıştır', 'İkisinin de librettosu Wagner\'e aittir'], 'Sevil Berberi Beaumarchais\'nin ilk Figaro oyununu, Figaro\'nun Düğünü ise devam oyununu konu alır; öykü sırasına göre Rossini\'ninki önce gelir.'),
  ('Puccini\'nin \'Madama Butterfly\' ve \'Turandot\' operalarında görülen, uzak kültürleri sahneye taşıma eğilimi hangi kavramla açıklanır?', 'Egzotizm', ['Neoklasisizm', 'Dodekafoni', 'Minimalizm'], '19. ve erken 20. yüzyıl Avrupa sanatında Japonya, Çin, Doğu gibi uzak kültürlere duyulan ilgi egzotizm olarak adlandırılır.'),
  ('Brahms\'ın ilk senfonisini 40\'lı yaşlarında, yaklaşık iki on yıllık bir çalışmanın sonunda tamamlamasının nedeni olarak en sık hangisi gösterilir?', 'Beethoven\'ın gölgesinde kalma kaygısı', ['Orkestra bulamaması', 'Senfoni türünün yasaklanması', 'Bütün zamanını opera bestelemeye ayırması'], 'Brahms\'ın \'Arkamızdan gelen bir devin ayak seslerini duymak\' sözü, Beethoven\'ın mirasının üzerinde yarattığı baskıyı anlatır.'),
  ('Brahms\'ın 1. Senfonisi\'nin, bir şef tarafından \'Beethoven\'ın Onuncusu\' diye anılmasının nedeni nedir?', 'Beethoven geleneğini sürdürmesi ve finalinin Dokuzuncu\'yu anımsatması', ['Beethoven\'ın yarım bıraktığı notalardan yapılmış olması', 'Beethoven\'ın ölümünden önce Brahms\'a ısmarlanmış olması', 'Tamamen Beethoven\'ın ezgilerinden oluşması'], 'Şef Hans von Bülow\'a atfedilen bu niteleme, finaldeki geniş ezginin \'Neşeye Övgü\'ye yakınlığına ve eserin Klasik senfoni geleneğine bağlılığına işaret eder.'),
  ('Brahms\'ın \'Alman Requiem\'ini geleneksel Katolik requiemlerinden ayıran özellik nedir?', 'Latince ayin metni yerine Almanca İncil metinleri kullanması', ['Hiçbir metin içermemesi', 'Yalnızca solo piyano için yazılmış olması', 'Tamamen İtalyanca opera aryalarından oluşması'], 'Brahms ölülerden çok yaşayanların teselli edilmesine odaklanan, kendi seçtiği Almanca İncil metinlerini kullanmıştır.'),
  ('Brahms\'ın eserlerine en uygun genel nitelendirme hangisidir?', 'Romantik duyarlığı Klasik biçim geleneğiyle birleştiren müzik', ['Klasik biçimleri reddeden serbest program müziği', 'Yalnızca opera sahnesi için yazılmış müzik', 'Halk ezgilerinden hiç yararlanmayan deneysel müzik'], 'Brahms senfoni, konçerto ve oda müziğinde sonat biçimi, varyasyon ve kontrpuan gibi geleneksel teknikleri Romantik bir ifadeyle işlemiştir.'),
  ('Rus milliyetçi müziğinin babası sayılan ve \'Çar İçin Bir Hayat\' operasını yazan besteci kimdir?', 'Mihail Glinka', ['Pyotr İlyiç Çaykovski', 'Mili Balakirev', 'Aleksandr Dargomijski'], 'Glinka 1836\'da sahnelenen bu operasıyla Rus halk ezgilerini ve konularını sanat müziğine taşıyarak sonraki kuşakları etkilemiştir.'),
  ('Rus Beşleri\'nin üyelerinin çoğunun profesyonel müzisyen olmaması hangi örnekle açıklanabilir?', 'Borodin\'in aynı zamanda tanınmış bir kimyager olması', ['Balakirev\'in Paris Operası\'nın şefi olması', 'Musorgski\'nin Viyana\'da konservatuvar yöneticisi olması', 'Cui\'nin yalnızca kilise orgcusu olması'], 'Borodin kimyager, Cui askerî mühendis, Musorgski memur, Rimski-Korsakov ise başlangıçta deniz subayıydı.'),
  ('Musorgski\'nin \'Boris Godunov\' operasının Rus Beşleri\'nin idealleriyle uyumlu yanı hangisidir?', 'Rus tarihini ve Rusçanın doğal vurgularına uyan bir ezgi dilini kullanması', ['İtalyan bel canto kurallarına sıkı sıkıya bağlı kalması', 'Almanca libretto ile yazılmış olması', 'Tamamen Fransız saray balelerinden oluşması'], 'Musorgski, Puşkin\'in tarihî dramına dayanan bu operada Rusça konuşma ritimlerini ezgiye yansıtmaya ve halkı (koroyu) başlıca karakter yapmaya çalışmıştır.'),
  ('Çaykovski\'nin yıllarca yüz yüze görüşmeden mektuplaştığı ve ona düzenli maddi destek veren hamisi kimdir?', 'Nadejda von Meck', ['Clara Schumann', 'Prenses Carolyne zu Sayn-Wittgenstein', 'Cosima Wagner'], 'Zengin bir dul olan von Meck, 1877\'den 1890\'a dek Çaykovski\'ye yıllık bir gelir bağlamış; ikisi bu süre boyunca neredeyse hiç karşılaşmamıştır.'),
  ('Çaykovski\'nin Rus Beşleri\'yle karşılaştırıldığında farklı bir yolda durduğu söylenir. Bu farkı en iyi hangisi açıklar?', 'Batılı biçimleri Rus duyarlığıyla birleştirmesi', ['Rus halk ezgilerini hiç kullanmamış olması', 'Yalnızca kilise müziği yazmış olması', 'Rusya dışına hiç çıkmamış olması'], 'Çaykovski St. Petersburg Konservatuvarı\'nın ilk mezunlarındandı; Beşler\'in aksine Batılı biçim ve tekniklere dayanmış, ama Rus ezgilerinden de yararlanmıştır.'),
  ('Çaykovski\'nin son senfonisi olan 6. Senfoni \'Pathétique\'in alışılmadık yönü nedir?', 'Parlak bir finalle değil, ağır ve kederli bir bölümle bitmesi', ['Koro ve solistler içermesi', 'Yalnızca iki bölümden oluşması', 'Bütünüyle bir halk dansından oluşması'], 'Senfoni, sönerek biten ağır bir Adagio lamentoso ile kapanır; Çaykovski eserin ilk seslendirmesinden dokuz gün sonra ölmüştür.'),
  ('Çaykovski\'nin Puşkin\'in manzum romanına dayanan ve Tatyana\'nın mektup sahnesiyle ünlü operası hangisidir?', 'Yevgeni Onegin', ['Maça Kızı', 'Boris Godunov', 'Ruslan ve Lyudmila'], 'Yevgeni Onegin, Puşkin\'in eserinden uyarlanmış ve 1879\'da Moskova Konservatuvarı öğrencileri tarafından sahnelenmiştir.'),
  ('Antonín Dvořák\'ın \'Yeni Dünya\' Senfonisi\'ni bestelediği dönem ve yer hangisidir?', '1893\'te New York\'ta konservatuvar yöneticisiyken', ['1850\'de Prag\'da öğrenciyken', '1870\'te Viyana\'da saray bestecisiyken', '1900\'de Londra\'da emekliyken'], 'Dvořák 1892–1895 yıllarında New York\'taki Ulusal Konservatuvar\'ı yönetmiş; Yeni Dünya Senfonisi bu dönemde Amerikan izlenimleriyle yazılmıştır.'),
  ('Dvořák\'ın Amerika\'dayken yerel müzik geleneklerine ilişkin önerisi neydi?', 'Afro-Amerikan ve yerli ezgilerden yararlanılması gerektiği', ['Amerikan müziğinin yalnızca Alman modellerini taklit etmesi gerektiği', 'Amerika\'da opera yazılmasının yasaklanması gerektiği', 'Halk ezgilerinin sanat müziğinden tamamen uzak tutulması gerektiği'], 'Dvořák, Amerikan ulusal müziğinin spiritüeller ve yerli ezgiler gibi kendi kaynaklarına dayanması gerektiğini savunmuştur.'),
  ('Jean Sibelius\'un 1899\'da yazdığı \'Finlandiya\' adlı eseri neden kısa sürede ulusal bir simgeye dönüşmüştür?', 'Rus yönetimindeki Finlerin ulusal duygularını dile getirdiği için', ['Finlandiya\'nın kraliyet düğünü için yazıldığı için', 'Fin dilinde yazılmış ilk opera olduğu için', 'Olimpiyat oyunları için resmi marş seçildiği için'], 'Eser Rus sansürüne karşı düzenlenen bir etkinlik için yazılmış ve Fin ulusal bilincinin simgesi olmuştur; bazı yerlerde başka adlarla çalınmak zorunda kalınmıştır.'),
  ('Sibelius\'un \'Tuonela\'nın Kuğusu\' ve \'Kullervo\' gibi eserlerinin konularını aldığı kaynak hangisidir?', 'Fin ulusal destanı Kalevala', ['İzlanda sagaları ve Edda şiirleri', 'Nibelungen Destanı', 'Homeros\'un İlyada\'sı'], 'Elias Lönnrot\'un derlediği Kalevala, Sibelius\'un birçok eserine konu olmuş ve Fin ulusal kimliğinin temel kaynaklarından biri sayılmıştır.'),
  ('Gustav Mahler\'in senfonileri için yaptığı ünlü değerlendirme \'Senfoni bir dünya gibi olmalı, her şeyi kucaklamalı\' sözüdür. Bu söz onun senfonilerinin hangi özelliğini açıklar?', 'Çok uzun, geniş kadrolu ve çok çeşitli öğeleri içeren yapısını', ['Kısa ve tek bölümlü olmalarını', 'Yalnızca yaylı çalgılar için yazılmalarını', 'Halk ezgilerinden hiç yararlanmamalarını'], 'Mahler\'in senfonilerinde askerî marşlar, halk dansları, ilahiler, şarkılar ve koro gibi çok çeşitli öğeler dev bir bütün içinde yer alır.'),
  ('Gustav Mahler yaşadığı dönemde bestecilikten çok hangi görevle ün kazanmıştı?', 'Viyana Saray Operası\'nın şefi ve yöneticisi olarak', ['Bir kilisenin orgcusu olarak', 'Bir konservatuvarın kemancısı olarak', 'Bir gazetenin müzik eleştirmeni olarak'], 'Mahler 1897–1907 yılları arasında Viyana Saray Operası\'nı yönetmiş, besteciliğini daha çok yaz tatillerinde sürdürmüştür.'),
  ('Anton Bruckner\'in senfonilerinin geniş, katedral gibi yükselen ses yapısı hangi geçmişiyle ilişkilendirilir?', 'Uzun yıllar kilise orgcusu olarak çalışmasıyla', ['Uzun yıllar askerî bando şefliği yapmasıyla', 'Opera şarkıcısı olarak yetişmesiyle', 'Caz kulüplerinde piyanistlik yapmasıyla'], 'Bruckner St. Florian Manastırı ve Linz Katedrali\'nde orgcuydu; orkestrasının blok halinde değişen tınıları org kayıtlarını anımsatır.'),
  ('Richard Strauss\'un \'Salome\' ve \'Elektra\' operalarının 1900\'lerin başında büyük tartışma yaratmasının nedeni nedir?', 'Şiddetli konuları ve sert, uyumsuz armonileri', ['Tamamen konuşmalı olmaları', 'Yalnızca çocuklar için yazılmış olmaları', 'Hiç orkestra içermemeleri'], 'Bu operalar yoğun psikolojik gerilimi büyük orkestra ve kromatik, yer yer atonaliteye yaklaşan bir dille anlatır.'),
  ('Aşağıdaki bestecilerden hangisi geç Romantizmin büyük orkestralı senfonik geleneğiyle en az ilişkilidir?', 'Erik Satie', ['Gustav Mahler', 'Anton Bruckner', 'Richard Strauss'], 'Satie sade, kısa ve ironik piyano parçalarıyla tanınır; geç Romantik gösterişe karşı tavır alan bir besteci olarak bilinir.'),
  ('Bizet\'nin \'Carmen\'i 1875\'te Opéra-Comique seyircisini şaşırtmıştı. Bunun en olası nedeni hangisidir?', 'Şiddetle biten sonu ve kuralları hiçe sayan kadın kahramanı', ['Operanın tamamen Almanca yazılmış olması ve konuşma içermemesi', 'Orkestranın sahnede değil, salonun dışında çalması', 'Eserin hiç kadın karakter içermemesi ve yalnızca erkek korosu kullanması'], 'Opéra-Comique aile seyircisine hitap eden bir salondu; bir kadın kahramanın sahnede öldürülmesi ve Carmen\'in kişiliği seyirciyi sarsmıştı.'),
  ('Saint-Saëns\'ın \'Danse macabre\' (Ölüm Dansı) adlı senfonik şiirinde akordu bilerek değiştirilmiş bir kemanın çaldığı ezgi neyi temsil eder?', 'Gece yarısı iskeletleri dansa çağıran Ölüm\'ü', ['Bir köy düğününde çalan çalgıcıyı', 'Ormanda uyuyan bir prensesi', 'Dalgalı bir denizde yol alan gemiyi'], 'Ölüm, en üst teli yarım ton pesleştirilmiş kemanla iskeletleri dansa çağırır; horoz ötüşünü taklit eden obua ile şafak söker ve dans sona erer.'),
  ('Charles Gounod\'nun Goethe\'nin eserine dayanan ve 19. yüzyılda en çok sahnelenen Fransız operalarından biri olan eseri hangisidir?', 'Faust', ['Carmen', 'Werther', 'Hoffmann\'ın Masalları'], 'Gounod\'nun Faust\'u 1859\'da sahnelenmiş; Mefistofeles\'in \'Altın Buzağı\' şarkısı ve \'Asker Korosu\' gibi bölümleriyle ünlenmiştir.'),
  ('Gabriel Fauré\'nin Requiem\'ini Berlioz ya da Verdi\'nin requiemlerinden ayıran özellik nedir?', 'Kıyamet korkusu yerine huzuru ve teselliyi öne çıkarması', ['Çok büyük bir orkestra ve dört ayrı bakır grubu kullanması', 'Opera sahnesi için yazılmış olması', 'Latince yerine İngilizce metin kullanması'], 'Fauré dramatik \'Dies irae\' sekansını büyük ölçüde dışarıda bırakmış ve \'In paradisum\' ile biten dingin bir eser yazmıştır.'),
  ('Debussy\'nin, Stéphane Mallarmé\'nin bir şiirinden esinlenerek yazdığı ve solo flütün ezgisiyle açılan orkestra eseri hangisidir?', 'Bir Kır Tanrısının Öğleden Sonrası\'na Prelüd', ['Deniz', 'Ay Işığı', 'Bolero'], '1894\'te seslendirilen eser, geleneksel uyum ve biçim kurallarını gevşeterek 20. yüzyıl müziğinin başlangıç noktalarından biri sayılır.'),
  ('Debussy\'nin müziğinde sıkça kullandığı ve \'tam ton dizisi\' gibi alışılmamış dizilerin seçilmesinin dinleyiciye etkisi nedir?', 'Tonal merkezi zayıflatıp belirsiz, yüzen bir hava yaratması', ['Her cümlenin güçlü bir kadansla bitmesini sağlaması', 'Müziği tamamen ritimsiz kılması', 'Eserin yalnızca tek bir akordan oluşmasına yol açması'], 'Tam ton dizisinde yarım ton bulunmadığı için çekim merkezi zayıflar; bu da Debussy\'nin müziğine sisli ve askıda bir karakter kazandırır.'),
  ('Debussy\'nin 1889 Paris Dünya Fuarı\'nda dinleyip etkilendiği ve müziğindeki tını anlayışını değiştirdiği bilinen gelenek hangisidir?', 'Cava gamelan müziği', ['Amerikan caz müziği', 'İskoç gayda müziği', 'Ortaçağ trubadur şarkıları'], 'Debussy fuarda dinlediği Cava gamelan topluluğunun katmanlı, çan sesine benzeyen tınısından etkilenmiştir; \'Pagodes\' gibi eserlerinde bu etki duyulur.'),
  ('Ravel\'in Birinci Dünya Savaşı\'nda sağ kolunu kaybeden piyanist Paul Wittgenstein için yazdığı eser hangisidir?', 'Sol El İçin Piyano Konçertosu', ['Sol majör Piyano Konçertosu', 'Gaspard de la nuit', 'Pavane pour une infante défunte'], 'Wittgenstein yalnızca sol eliyle çalabiliyordu; Ravel\'in 1930\'da yazdığı bu konçerto tek elle çalınan en ünlü eserlerdendir.'),
  ('Stravinski\'nin \'Bahar Ayini\'nin müziğinde dinleyiciyi en çok sarsan yön hangisidir?', 'Sürekli değişen ölçüler ve beklenmedik vurgular', ['Yalnızca Gregoryen ilahilerden oluşması', 'Tek bir çalgı için yazılmış olması', 'Tamamen sessiz geçen uzun bölümler içermesi'], 'Eserin \'Kurban Dansı\' gibi bölümlerinde ölçü neredeyse her ölçüde değişir ve vurgular düzensiz bir enerjiyle yer değiştirir.'),
  ('Stravinski\'nin erken balelerini Paris\'te sahneleyen ünlü bale topluluğu ve yöneticisi hangisidir?', 'Ballets Russes – Sergey Diyagilev', ['Bolşoy Balesi – Marius Petipa', 'Paris Opera Balesi – Jean-Baptiste Lully', 'New York City Ballet – Leonard Bernstein'], 'Diyagilev\'in Ballets Russes topluluğu Ateş Kuşu, Petruşka ve Bahar Ayini\'ni sahnelemiş; Ravel, Debussy ve Prokofiev\'e de eser ısmarlamıştır.'),
  ('Stravinski\'nin 1920\'lerden itibaren 18. yüzyıl müziğinin biçim ve üsluplarına yönelerek \'Pulcinella\' gibi eserler yazması hangi akıma örnektir?', 'Neoklasisizm', ['Empresyonizm ve sembolizm', 'Verismo', 'Minimalizm'], 'Neoklasisizm, Romantik aşırılıklara tepki olarak Barok ve Klasik dönemin denge ve saydamlığına modern bir uyum diliyle dönmeyi ifade eder.'),
  ('Schoenberg\'in \'Pierrot Lunaire\' (1912) adlı eserinde şarkıcının ne konuşup ne şarkı söylediği, perdeye yalnızca dokunup geçtiği vokal tekniğe ne ad verilir?', 'Sprechstimme', ['Bel canto', 'Melizma', 'Falseto (kafa sesi) tekniği'], 'Sprechstimme (\'konuşan ses\') şarkı ile konuşma arasında kalan bir anlatımdır; Pierrot Lunaire\'in tuhaf ve dışavurumcu havasını güçlendirir.'),
  ('Anton Webern\'in eserlerini Berg ve Schoenberg\'in eserlerinden ayıran en belirgin özellik nedir?', 'Son derece kısa, yoğun ve seyrek dokulu olmaları', ['Saatlerce süren opera döngüleri olmaları', 'Halk şarkılarına ve köy danslarına dayanan uzun süitler olmaları', 'Yalnızca piyano için yazılmış olmaları'], 'Webern\'in bazı eserleri bir dakikadan kısa sürer; her notanın ağırlık taşıdığı bu yoğun, aforizmaya benzeyen yazı savaş sonrası dizisel besteciler için model olmuştur.'),
  ('Schoenberg\'in müzik dilini köklü biçimde değiştiren yolculuğu hangi sırayla gerçekleşmiştir?', 'Geç Romantik tonalite → serbest atonalite → on iki ton yöntemi', ['On iki ton yöntemi → serbest atonalite → geç Romantik tonalite', 'Serbest atonalite → geç Romantik tonalite → on iki ton yöntemi', 'Barok modal yazı → minimalizm → empresyonizm → tonalite'], 'Schoenberg \'Verklärte Nacht\' (1899) gibi geç Romantik eserlerle başlamış, 1908\'den sonra atonaliteye, 1920\'lerde de on iki ton yöntemine geçmiştir.'),
  ('Nazi rejiminin \'yozlaşmış müzik\' (Entartete Musik) olarak damgaladığı bestecilerin başına gelenlere en iyi örnek hangisidir?', 'Schoenberg\'in ABD\'ye göç etmek zorunda kalması', ['Wagner\'in eserlerinin yasaklanması', 'Beethoven\'ın senfonilerinin yakılması', 'Bach\'ın kiliselerden çıkarılması'], 'Yahudi kökenli Schoenberg 1933\'te Berlin\'deki görevinden uzaklaştırılmış ve Los Angeles\'a yerleşerek orada ders vermiştir.'),
  ('Bartók ve Kodály\'nin halk müziğine yaklaşımı Liszt\'in \'Macar Rapsodileri\'nden hangi bakımdan ayrılır?', 'Köy müziğini yerinde kaydedip bilimsel olarak incelemeleri', ['Halk ezgilerini hiç kullanmamaları', 'Yalnızca kentli Roman orkestralarını örnek almaları', 'Halk ezgilerini İtalyan operasına uyarlamaları'], 'Bartók ve Kodály gerçek köylü müziğini sahada derlemiş, dizilerini ve ritimlerini inceleyip kendi modern dillerine kaynaştırmıştır.'),
  ('Bartók\'un piyano eğitimi için yazdığı, kolaydan zora doğru ilerleyen altı ciltlik dizi hangisidir?', 'Mikrokosmos', ['Allegro barbaro', 'Sonatin', 'Çocuklar İçin Albüm'], 'Mikrokosmos 153 parçadan oluşur ve hem piyano tekniğini hem de Bartók\'un modern ses dilini adım adım tanıtır.'),
  ('Bartók\'un ABD\'de yaşamının son yıllarında Boston Senfoni Orkestrası\'nın şefi Koussevitzky\'nin ısmarlamasıyla yazdığı eser hangisidir?', 'Orkestra İçin Konçerto', ['Yaylılar, Vurmalılar ve Çelesta İçin Müzik', 'Mavi Sakal\'ın Şatosu', 'Mucizevi Mandalina'], 'Orkestra İçin Konçerto 1944\'te seslendirilmiş; her çalgı grubuna solist gibi parlama fırsatı veren yapısıyla Bartók\'un en sevilen eserlerinden biri olmuştur.'),
  ('Prokofiev\'in 1. Senfonisi\'ne \'Klasik\' adını vermesinin nedeni nedir?', 'Haydn bugün yaşasa yazabileceği gibi bir senfoni tasarlaması', ['Senfoniyi Bach\'ın notalarından derlemesi', 'Eserin Antik Yunan müziğine dayanması', 'Senfoninin yalnızca Barok çalgılarla çalınması'], 'Prokofiev 1917\'de Haydn\'ın biçim ve kadro ölçülerine uyan, ama esprili ve modern dokunuşlar taşıyan bir senfoni yazmış; eser neoklasisizmin erken örneklerindendir.'),
  ('Dmitri Şostakoviç\'in \'Mtsenskli Leydi Makbet\' operasının 1936\'da Pravda gazetesinde \'müzik yerine karmaşa\' başlıklı bir yazıyla eleştirilmesi neyi gösterir?', 'Devletin sanatı siyasi denetim altına almaya çalıştığını', ['Operanın Sovyetler Birliği\'nde hiç sahnelenmediğini', 'Şostakoviç\'in operayı kendisinin yasakladığını', 'Eleştirmenlerin eseri yalnızca teknik yönden değerlendirdiğini'], 'Stalin\'in opera gösterisini izledikten sonra çıkan bu yazı, Şostakoviç\'in kariyerini ve hayatını tehlikeye atmış, bestecileri sosyalist gerçekçiliğe uymaya zorlamıştır.'),
  ('Şostakoviç\'in 7. Senfonisi \'Leningrad\' neden simgesel bir önem kazanmıştır?', 'Kuşatılmış kentte 1942\'de seslendirilip direnişin simgesi olduğu için', ['Ekim Devrimi\'nin yıldönümü için kilisede çalındığı için', 'Sovyetler Birliği\'nin resmî ulusal marşı olduğu için', 'Leningrad\'ın kuruluşunu anlatan bir bale olduğu için'], 'Senfoni kuşatılmış Leningrad\'da aç ve hasta müzisyenlerle seslendirilmiş, hoparlörlerle düşman hatlarına da yayınlanmıştır.'),
  ('Bir müzik tarihçisi şöyle yazıyor: \'Bu besteci Batı\'da yıllarca yaşadıktan sonra 1930\'larda Sovyetler Birliği\'ne kesin olarak döndü.\' Tarihçi hangi besteciden söz etmektedir?', 'Sergey Prokofiev', ['Dmitri Şostakoviç', 'Sergey Rahmaninov', 'İgor Stravinski'], 'Prokofiev 1918\'de Rusya\'dan ayrılmış, ABD ve Paris\'te yaşamış, 1936\'da ailesiyle Moskova\'ya yerleşmiştir. Rahmaninov ve Stravinski ise bir daha dönmemiştir.'),
  ('Rahmaninov\'un 1917 Devrimi\'nden sonra Rusya\'dan ayrılmasının kariyerine etkisi ne olmuştur?', 'Geçimini daha çok piyanistlikle sağlaması', ['Besteciliği bırakıp kimyager olması', 'Sovyet devletinin resmi bestecisi olması', 'Konser vermeyi bırakıp manastıra çekilmesi'], 'Rahmaninov ABD\'ye yerleşince yoğun konser turnelerine çıkmış; bu yüzden göçten sonra çok daha az eser bestelemiştir.'),
  ('Rahmaninov\'un Paganini\'nin bir kaprisi üzerine yazdığı ve 18. varyasyonu ayrıca çok ünlenen piyano ve orkestra eseri hangisidir?', 'Paganini Teması Üzerine Rapsodi', ['Corelli Teması Üzerine Varyasyonlar', '3. Piyano Konçertosu', 'Senfonik Danslar'], '1934\'te yazılan rapsodinin 18. varyasyonunda Paganini temasının tersine çevrilmesiyle geniş, romantik bir ezgi elde edilmiştir.'),
  ('İngiltere\'de \'Land of Hope and Glory\' adıyla söylenen ezginin, Edward Elgar\'ın hangi eserinden alındığı bilinir?', '1 numaralı Pomp and Circumstance Marşı', ['Enigma Varyasyonları\'nın Nimrod bölümü', 'Gerontius\'un Rüyası', 'Viyolonsel Konçertosu'], 'Elgar\'ın 1901\'de yazdığı marşın orta bölümüne sonradan sözler yazılmış; ezgi ABD\'de mezuniyet törenlerinde de çalınır.'),
  ('Elgar\'ın \'Enigma Varyasyonları\'nın her varyasyonu neyi betimler?', 'Bestecinin çevresinden bir dostunu ya da eşini', ['Bir Shakespeare oyununun her perdesini', 'İngiltere\'nin farklı kentlerini', 'Yılın on dört ayrı mevsimini'], 'Elgar her varyasyonu bir kişiye adamış ve başına baş harflerini ya da takma adlarını yazmıştır; \'Nimrod\' varyasyonu dostu Jaeger\'i betimler.'),
  ('Holst\'un \'Gezegenler\' süitinde Dünya ve Plüton neden yer almaz?', 'Dünya astrolojide ele alınmadığı, Plüton ise henüz bilinmediği için', ['İki bölümü sonradan kaybolduğu için', 'Plüton\'un adı müziğe uymadığı için', 'Holst bu iki gezegeni hiç sevmediği için'], 'Süit 1914–1916\'da yazılmıştır; Plüton ancak 1930\'da keşfedilmiştir. Holst da gökbilimden çok astrolojik karakterlerle ilgilenmiştir.'),
  ('Ralph Vaughan Williams\'ın İngiliz müziğine en önemli katkılarından biri hangisidir?', 'Halk şarkılarını derleyip ulusal üslubun temeline koyması', ['İngiltere\'de ilk operayı yazması', 'Basso continuo\'yu İngiltere\'ye taşıması', 'On iki ton yöntemini İngiltere\'de bulması'], 'Vaughan Williams köylerde halk şarkıları derlemiş, bunları ve Tudor dönemi müziğini kaynak alarak Alman etkisinden bağımsız bir İngiliz üslubu oluşturmuştur.'),
  ('Vaughan Williams\'ın \'Thomas Tallis\'in Bir Teması Üzerine Fantezi\' adlı eseri neyi gösterir?', 'Bestecilerin Rönesans mirasına yeniden ilgi duyduğunu', ['Tallis\'in eseri bizzat 20. yüzyılda yazdığını', 'İngiliz müziğinin yalnızca Alman modellerine dayandığını', 'Eserin Tallis\'in bir operasından alındığını'], 'Vaughan Williams 16. yüzyıl bestecisi Tallis\'in bir mezmur ezgisini 20. yüzyıl yaylı orkestrası için işleyerek ulusal bir geçmişle bağ kurmuştur.'),
  ('Benjamin Britten\'ın bir balıkçı köyünde dışlanan bir balıkçının trajedisini anlatan ve 1945\'te sahnelenen operası hangisidir?', 'Peter Grimes', ['Billy Budd', 'Gloriana', 'Turn of the Screw'], 'Peter Grimes İngiliz operasının yeniden doğuşu sayılır; denizi betimleyen \'Dört Deniz Ara Müziği\' ayrıca konser eseri olarak da çalınır.'),
  ('Gershwin\'in \'Porgy and Bess\' eserine bestecinin kendisinin verdiği ad hangisidir?', 'Halk operası (folk opera)', ['Opera buffa', 'Operet (hafif opera)', 'Oratoryo'], 'Gershwin bu eseri Güney Carolina\'daki Afro-Amerikan topluluğun yaşamını anlatan bir \'Amerikan halk operası\' olarak tanımlamış; \'Summertime\' aryası buradan çıkmıştır.'),
  ('Aaron Copland\'ın \'Appalachian Spring\' ve \'Rodeo\' gibi eserlerinin ortak özelliği hangisidir?', 'Halk ezgileri ve yalın uyumlarla kırsal Amerika\'yı çağrıştırmaları', ['Atonal ve dizisel bir dille yazılmış olmaları', 'Avrupa saray danslarını taklit etmeleri', 'Elektronik seslerle oluşturulmuş olmaları'], 'Copland, Shaker ilahisi \'Simple Gifts\' gibi yerel ezgileri ve yalın uyumları kullanarak kırsal Amerika\'yı çağrıştıran bir üslup yaratmıştır.'),
  ('Samuel Barber\'ın bir yaylı dörtlüsünün ağır bölümünden düzenlenen ve devlet cenazeleri gibi yas anlarında sık çalınan eseri hangisidir?', 'Adagio for Strings', ['Rhapsody in Blue', 'Fanfare for the Common Man', 'Short Ride in a Fast Machine'], 'Barber\'ın 1936\'da yazdığı yaylı dörtlüsünün ikinci bölümü, Toscanini\'nin 1938\'deki radyo yayınıyla ünlenmiştir.'),
  ('1920\'lerde Paris\'te Satie ve Jean Cocteau çevresinde anılan, Poulenc, Milhaud ve Honegger\'in de aralarında bulunduğu besteciler grubuna ne ad verilir?', 'Altılar', ['Rus Beşleri', 'İkinci Viyana Okulu', 'Darmstadt Okulu ve öğrencileri'], 'Altılar, Alman Romantizmine ve Debussy\'nin izlenimciliğine karşı, kabare, sirk ve caz gibi gündelik müziklerden beslenen açık ve esprili bir müzik savunmuştur.'),
  ('Altılar grubunun estetik tavrını en iyi özetleyen ifade hangisidir?', 'Gündelik yaşamın sade ve neşeli müziğine yönelmek', ['Wagner\'in müzikli dramını Fransa\'da yeniden canlandırmak', 'Yalnızca Gregoryen ilahiye dayanan kilise müziği yazmak', 'On iki ton yöntemini Paris\'te yaymak'], 'Cocteau\'nun \'Horoz ve Harlequin\' adlı yazısında savunduğu gibi grup, büyük ve ağdalı müzik yerine kısa, açık ve gündelik bir anlatımı benimsemiştir.'),
  ('Olivier Messiaen\'in Görlitz yakınlarındaki bir esir kampında bestelediği ve ilk kez orada mahkûmlara seslendirdiği eser hangisidir?', 'Zamanın Sonu İçin Dörtlü', ['Turangalîla Senfonisi', 'Kuş Kataloğu', 'İsa\'nın Doğuşu'], 'Messiaen 1941\'de Stalag VIII-A kampında, eldeki çalgılara göre klarnet, keman, viyolonsel ve piyano için yazdığı bu eseri soğuk bir barakada seslendirmiştir.'),
  ('Messiaen\'in Paris Konservatuvarı\'nda yetiştirdiği öğrenciler arasında aşağıdakilerden hangisi bulunur?', 'Pierre Boulez', ['Erik Satie', 'Claude Debussy', 'Maurice Ravel'], 'Boulez ve Stockhausen Messiaen\'in derslerine katılmış; öğretmenlerinin ritim ve ses yüksekliğini sistemli olarak düzenleme denemeleri onları etkilemiştir.'),
  ('John Cage\'in piyanonun tellerinin arasına vida, lastik ve tahta parçaları yerleştirerek elde ettiği çalgıya ne ad verilir?', 'Hazırlanmış piyano', ['Elektrikli piyano', 'Çeyrek ton piyanosu', 'Otomatik piyano'], 'Cage bu yöntemle piyanoyu küçük bir vurmalı çalgı topluluğuna dönüştürmüş, \'Sonatlar ve Interlüdler\' gibi eserler yazmıştır.'),
  ('Karlheinz Stockhausen\'in Köln\'deki elektronik müzik stüdyosunda yaptığı çalışmalar müzik tarihinde neyi temsil eder?', 'Seslerin elektronik olarak üretildiği yeni bir alanı', ['Barok org yapımının yeniden canlanmasını', 'Gregoryen ilahinin yeniden düzenlenmesini', 'Operanın sözsüz bir türe dönüşmesini'], 'Stockhausen 1950\'lerde \'Gençlerin Şarkısı\' gibi eserlerle elektronik sesleri ve kaydedilmiş insan sesini bir araya getirmiştir.'),
  ('Pierre Schaeffer\'in Paris\'te 1940\'ların sonunda geliştirdiği, kaydedilmiş gerçek seslerin (tren, kapı, ses) bant üzerinde işlenmesine dayanan müzik türü hangisidir?', 'Somut müzik (musique concrète)', ['Seri müzik', 'Spektral müzik (Fransız ekolü)', 'Minimal müzik'], 'Schaeffer\'in 1948\'deki \'Demiryolu Etüdü\', tren seslerinden oluşturulmuş ilk somut müzik eserlerinden biridir.'),
  ('Krzysztof Penderecki\'nin \'Hiroşima Kurbanları İçin Ağıt\' adlı eserinde yaylı çalgıların birbirine çok yakın sesleri aynı anda çalarak oluşturduğu yoğun ses yığınlarına ne ad verilir?', 'Ses kümesi (cluster)', ['Kanon', 'Arpej', 'Bas ostinato (ground bass)'], 'Penderecki 52 yaylı çalgı için yazdığı eserde geleneksel nota yerine bantlar ve özel işaretler kullanarak çığlığa benzer kümeler oluşturmuştur.'),
  ('György Ligeti\'nin \'Atmosphères\' gibi eserlerinin geniş kitlelerce tanınmasını sağlayan olay hangisidir?', 'Kubrick\'in \'2001: Bir Uzay Destanı\' filminde kullanılması', ['Bir olimpiyat açılışında çalınması', 'Bir ulusal marş olarak seçilmesi', 'Bir reklam şarkısına dönüştürülmesi'], 'Kubrick 1968\'deki filminde Ligeti\'nin eserlerini kullanmış; Ligeti\'den izin alınmadığı için sonradan anlaşmazlık çıkmıştır.'),
  ('İkinci Dünya Savaşı sonrası avangart müzik için aşağıdaki genellemelerden hangisi en doğrudur?', 'Tonaliteden uzaklaşıp yeni ses malzemeleri aradı', ['Yalnızca Barok biçimlerin aynen taklidine dayandı', 'Halk şarkılarını kilise korolarına uyarladı', 'Bütünüyle opera buffa türünde gelişti'], 'Bu dönemde dizisellik, elektronik müzik, rastlantısallık ve ses kütleleri gibi birbirinden farklı yollar denendi; ortak nokta gelenekle köklü bir kopuştu.'),
  ('Terry Riley\'nin 1964 tarihli \'In C\' adlı eserinde müzisyenler 53 kısa kalıbı sırayla, ama her biri istediği kadar tekrar ederek çalar. Bunun sonucu ne olur?', 'Her seslendirmede farklı bir üst üste binme dokusu', ['Her seslendirmede aynı ve değişmeyen bir sonuç', 'Eserin tek bir notadan oluşması ve hiç değişmemesi', 'Eserin yalnızca tek bir müzisyenle çalınabilmesi'], 'İcracıların tekrar sayısını kendilerinin belirlemesi, kalıpların her seferinde farklı biçimde örtüşmesine yol açar.'),
  ('Steve Reich\'ın \'It\'s Gonna Rain\' adlı eserinde aynı kaydı iki teyp makinesinde çalıp birinin hafifçe öne geçmesiyle elde ettiği teknik hangisidir?', 'Faz kayması', ['Kanon tersinmesi', 'Kromatik modülasyon ve geçiş akorları', 'Ritornello'], 'İki özdeş kayıt yavaşça birbirinden ayrıldıkça yeni ritim ve tını desenleri ortaya çıkar; Reich bu tekniği sonra canlı çalgılara uyarlamıştır.'),
  ('Philip Glass\'ın Robert Wilson ile birlikte hazırladığı ve geleneksel bir öyküsü olmayan, yaklaşık beş saat süren operası hangisidir?', 'Einstein on the Beach', ['Nixon in China', 'Akhnaten ve Satyagraha üçlemesi', 'Wozzeck'], '1976\'da sahnelenen bu opera, tekrarlanan sayılar ve heceler, sürekli yinelenen arpejler ve imgelerle minimalist müzik tiyatrosunun simgesi olmuştur.'),
  ('Estonyalı Arvo Pärt\'ın \'tintinnabuli\' adını verdiği üslubu hangi özelliğiyle tanınır?', 'Çan seslerini anımsatan çok yalın bir yazı', ['Sert ve gürültülü elektronik sesler', 'Karmaşık on iki ton dizileri', 'Hızlı, virtüöz ve süslemeli keman pasajları'], 'Tintinnabuli\'de bir ses bir ezgiyi adım adım ilerletirken diğer ses yalnızca bir üç sesli akorun notalarını çalar; sonuç sade ve dingin bir tınıdır.'),
  ('Barok konçerto ile Klasik dönem konçertosu karşılaştırıldığında, Klasik konçertoda öne çıkan yenilik hangisidir?', 'Solistin orkestrayla dramatik bir diyalog kurması', ['Basso continuo\'nun zorunlu hale gelmesi', 'Tek bir bölümden oluşması', 'Solistin hiç yer almaması'], 'Mozart\'ın konçertolarında solist ile orkestra senfonik bir çatışma ve uzlaşma içinde ilerler; bölümlerin içinde solistin doğaçlama kadansı da yer alır.'),
  ('Orta Çağ\'dan 19. yüzyıla uzanan süreçte bestecilerin geçimini sağladığı başlıca kaynaklar hangi sırayla değişmiştir?', 'Kilise → saray → kamusal konser ve yayıncılık', ['Kamusal konser → kilise → saray', 'Saray → kamusal konser → kilise', 'Yayıncılık → kilise → saray'], 'Orta Çağ bestecileri çoğunlukla kilisede çalışırdı; Barok ve Klasik dönemde saraylar öne çıktı; 19. yüzyılda bilet satılan konserler ve nota satışı belirleyici oldu.'),
  ('Bir öğrenci \'Senfoni türünün gelişimi\' konusunda bir sıralama yapıyor. Hangi sıralama doğrudur?', 'Haydn → Beethoven → Brahms → Mahler', ['Mahler → Haydn → Brahms → Beethoven', 'Beethoven → Haydn → Mahler → Brahms', 'Brahms → Mahler → Beethoven → Haydn'], 'Haydn senfoniyi Klasik dönemde biçimlendirmiş, Beethoven genişletmiş, Brahms Romantik dönemde sürdürmüş, Mahler ise geç Romantizmde devasa boyutlara taşımıştır.'),
  ('Bir müzik tarihçisi \'Bu dönemde besteciler yüzyıllardır kullanılan majör–minör ton sistemini terk etmeye başladı\' diyor. Tarihçi hangi dönemden söz etmektedir?', '20. yüzyılın başları', ['Barok dönemin başları', 'Rönesans\'ın ortaları', 'Klasik dönemin sonları'], 'Schoenberg ve çevresi 1908 dolaylarından itibaren tonal sistemi bırakan atonal eserler yazmaya başlamıştır.'),
  ('Barok ve Romantik dönemlerin müzikte duyguyu ele alışı karşılaştırıldığında hangisi doğrudur?', 'Barok\'ta bölüm tek duygulanımı korur, Romantik\'te duygu sık değişir', ['Barok\'ta duygu ifadesi yasaktı, Romantik\'te zorunluydu', 'İki dönemde de müziğin duyguyla ilgisi yoktu', 'Romantik\'te bir bölüm boyunca tek bir duygu korunurdu'], 'Barok duygulanım kuramı bölüm başına bir temel duygu öngörürken, Romantik besteciler duyguların iniş çıkışlarını ve kişisel ifadeyi öne çıkarmıştır.'),
  ('Bir öğrenci şu ifadeyi yazıyor: \'Opera Barok dönemin başında doğdu ve yüzyıllar boyunca gelişti.\' Bu ifadeyi destekleyen eser–yıl çiftlerinden hangisi kronolojik olarak doğru sıralanmıştır?', 'L\'Orfeo (1607) → Sihirli Flüt (1791) → Carmen (1875)', ['Carmen (1875) → L\'Orfeo (1607) → Sihirli Flüt (1791)', 'Sihirli Flüt (1791) → Carmen (1875) → L\'Orfeo (1607)', 'L\'Orfeo (1607) → Carmen (1875) → Sihirli Flüt (1791)'], 'Monteverdi\'nin L\'Orfeo\'su 1607\'de, Mozart\'ın Sihirli Flüt\'ü 1791\'de, Bizet\'nin Carmen\'i 1875\'te sahnelenmiştir.'),
  ('Rönesans çok sesliliği ile Klasik dönem dokusu arasındaki temel farkı en iyi hangisi açıklar?', 'Rönesans\'ta sesler eşit önemde, Klasik\'te ezgi–eşlik ayrımı belirgindir', ['Rönesans\'ta yalnızca tek ses, Klasik\'te yalnızca koro vardır', 'Klasik dönemde hiç eşlik kullanılmaz', 'Rönesans\'ta yalnızca çalgı müziği yazılmıştır'], 'Rönesans\'ta polifonik doku egemendi; Klasik dönemde belirgin bir ezgi ve onu destekleyen akor eşliğinden oluşan homofonik doku öne çıktı.'),
  ('Aşağıdaki tarihlerden hangisi Batı müziği tarihinde dönem sınırı olarak en sık kullanılır ve neden?', '1750, çünkü J. S. Bach\'ın öldüğü yıldır', ['1492, çünkü Amerika\'nın keşfedildiği yıldır', '1914, çünkü Romantik dönemin başladığı yıldır', '1800, çünkü opera o yıl doğmuştur'], 'Barok dönemin bitişi geleneksel olarak Bach\'ın ölüm yılı 1750 ile gösterilir; bu bir uzlaşmadır ve üslup değişimi aslında daha önce başlamıştır.'),
  ('Bir müzik eleştirmeni bir eser için \'Romantik çağın kişisel duygusallığından uzak, nesnel ve saydam bir yazı; Barok biçimlere modern bir uyumla dönüş\' diyor. Bu eser en çok hangi akıma yakındır?', 'Neoklasisizm', ['Verismo', 'Empresyonizm', 'Geç Romantizm'], 'Stravinski ve Prokofiev gibi bestecilerin 1920\'lerdeki eserleri bu tanıma uyar; neoklasisizm Romantik aşırılıklara bir tepkidir.'),
  ('Gregoryen ilahide ritmin düzenli bir ölçüye bağlı olmaması, ilahinin hangi amacıyla en iyi açıklanır?', 'Sözlerin doğal okunuşunu izleyip metni öne çıkarmak', ['Dansa eşlik etmek', 'Askerî yürüyüşlerde kullanılmak', 'Çalgıcıların ustalığını sergilemek'], 'İlahinin serbest ritmi Latince metnin vurgu ve söyleyişini izler; amaç dinleyiciyi eğlendirmek değil, metni ibadet havası içinde iletmektir.'),
  ('Guido d\'Arezzo\'nun yeniliklerinden önce bir koro çocuğunun yeni bir ilahiyi öğrenmesi yıllar sürebiliyordu. Guido\'nun yöntemi bu durumu nasıl değiştirmiştir?', 'Perdeleri çizgiler üzerinde göstererek ezgiyi okunur kılarak', ['İlahileri tamamen kaldırıp yalnızca çalgı müziği önererek', 'Bütün ilahileri tek bir ezgiye indirerek', 'Şarkıcıların ezgiyi doğaçlamasını zorunlu kılarak'], 'Guido, öğrencilerinin daha önce duymadıkları bir ilahiyi bile çizgili dizek ve hece sistemi sayesinde kısa sürede söyleyebildiğini yazmıştır.'),
  ('Hildegard von Bingen\'in 12. yüzyılda yaşamış bir kadın besteci olarak eserlerinin günümüze ulaşması neden dikkat çekicidir?', 'Adı bilinen Orta Çağ bestecisinin az, kadınların rolünün kısıtlı olması', ['O dönemde kadınların müzik dinlemesinin yasak olması', 'Eserlerinin basılı olarak satılması', 'Kendi orkestrasını kurmuş olması'], 'Orta Çağ müziğinin çoğu anonimdir; Hildegard\'ın hem adının hem de geniş bir eser külliyatının korunmuş olması bu yüzden ayrıca önemlidir.'),
  ('Protestan koralı ile Katolik Gregoryen ilahisi karşılaştırıldığında koralın hangi özelliği farklıdır?', 'Halkın kolayca söyleyebileceği, yerel dilde düzenli ezgiler olması', ['Latince ve tek sesli olması', 'Yalnızca eğitimli rahiplerin söyleyebilmesi', 'Hiçbir zaman çok sesli düzenlenmemesi'], 'Koraller dizeli, düzenli ritimli ve Almanca idi; cemaat tarafından söylenmek üzere tasarlanmış, zamanla dört sesli olarak da uyumlanmıştır.'),
  ('Floransa Camerata\'sının çok sesli madrigale yönelttiği eleştiri, aşağıdakilerden hangisiyle en iyi özetlenir?', 'Aynı anda farklı sözler söylenmesi şiirin anlaşılmasını engelliyordu', ['Madrigaller fazla kısa ve neşeliydi', 'Madrigaller yalnızca çalgılarla çalınıyordu', 'Madrigallerde hiç uyumsuzluk yoktu'], 'Camerata üyeleri, örneğin Vincenzo Galilei, Antik Yunan\'da şiirin tek bir sesle söylendiğini düşünerek çok sesliliğin sözü boğduğunu ileri sürmüştür.'),
  ('Bir Barok aryasında A bölümünün ardından karşıt bir B bölümü gelir, sonra A bölümü şarkıcının süslemeleriyle yeniden söylenir. Bu yapıya ne ad verilir?', 'Da capo aryası', ['Strofik şarkı', 'Rondo finali', 'Tema ve varyasyon'], '\'Da capo\' baştan anlamına gelir; şarkıcıdan A bölümünün dönüşünde kendi süslemelerini eklemesi beklenirdi.'),
  ('Vivaldi\'nin \'Dört Mevsim\'inin \'Kış\' konçertosunda yaylıların kısa ve sert tekrarlanan notaları, eşlik eden sonedeki hangi imgeyle ilişkilendirilir?', 'Soğukta titreyen ve dişleri takırdayan insanlar', ['Yaz sıcağında öten kuşlar', 'Bahar şenliğinde dans eden çobanlar ve köylüler', 'Sonbahardaki av köpekleri'], 'Kış konçertosunun açılışında tekrarlanan sert akorlar ve titreyen sesler, sonedeki dondurucu soğuk ve takırdayan dişleri betimler.'),
  ('Bach\'ın Leipzig\'de her pazar ayini için yeni kantatlar hazırlaması, bir 18. yüzyıl kilise müzisyeninin görevleri hakkında ne söyler?', 'Bestecinin düzenli olarak işlevsel müzik üretmekle yükümlü olduğunu', ['Bestecinin yalnızca tatillerde müzik yazdığını', 'Kilise müziğinin hep eski eserlerden oluştuğunu', 'Bestecilerin yalnızca kendileri için yazdığını'], 'Thomaskantor, okul öğretmenliği, korolar ve kentin kiliselerinin müziğinden sorumluydu; yeni müzik yazmak işin olağan bir parçasıydı.'),
  ('Bach\'ın bir koral ezgisini alıp dört ses için uyumlaması ve kantatın sonunda cemaatin tanıdığı bu ezgiyi duyması hangi amaca hizmet eder?', 'Cemaati tanıdık ezgi aracılığıyla ibadete bağlamak', ['Dinleyicileri şaşırtıp eğlendirmek', 'Kantatı sahnelenen bir operaya dönüştürmek', 'Eserin süresini kısaltmak'], 'Kantatın sonundaki koral, metnin mesajını herkesin bildiği ezgiyle özetler ve ibadetin ortak bir anına dönüşür.'),
  ('Händel\'in \'Messiah\' oratoryosunun Londra\'da her yıl hayır amaçlı konserlerle seslendirilmesi, oratoryo türünün toplumsal işlevi hakkında ne gösterir?', 'Oratoryonun kamusal ve hayır etkinliklerinde geniş kitleye seslendiğini', ['Oratoryonun yalnızca saray için yazıldığını', 'Oratoryonun dinsel konular işleyemediğini', 'Oratoryonun yalnızca kapalı manastırlarda dinlendiğini'], 'Händel Messiah\'ı Foundling Hospital (kimsesiz çocuklar yurdu) yararına düzenli olarak yönetmiş; eser geniş halk kitlelerinin sevdiği bir esere dönüşmüştür.'),
  ('Händel\'in \'Su Müziği\'nin açık havada bir nehirde çalınacak olması, bestecinin çalgı seçimini nasıl etkilemiş olabilir?', 'Uzaktan duyulan güçlü üflemelilere yer vermesine', ['Yalnızca klavsen kullanmasına', 'Yaylıları tamamen çıkarıp koro kullanmasına', 'Çok kısık ve fısıltılı bir müzik yazmasına'], 'Açık havada sesin dağılması nedeniyle kornolar, trompetler ve obualar gibi gür çalgılar Su Müziği\'nde belirgin bir yer tutar.'),
  ('Gluck\'un \'Orfeo ed Euridice\' operasında Orfeo\'nun ağıtının süslemesiz ve yalın olması, Gluck\'un reform anlayışıyla nasıl bağdaşır?', 'Duygunun gösterişsiz ve doğal biçimde ifade edilmesi', ['Şarkıcının virtüözlüğünü sergileme isteği', 'Eseri bir dans süitine dönüştürme amacı', 'Sözlerin anlaşılmaz olmasını sağlama isteği'], 'Gluck\'a göre müzik dramın hizmetindeydi; \'Che farò senza Euridice\' aryasının sadeliği bu ilkenin örneğidir.'),
  ('Mannheim orkestrasını dinleyen 18. yüzyıl dinleyicilerinin uzun crescendolar sırasında heyecanla ayağa kalktığı anlatılır. Bu tepki neyi gösterir?', 'Kademeli gürlük artışının o dönem için yeni ve etkileyici olduğunu', ['Dinleyicilerin konserden sıkıldığını', 'Orkestranın akort sorunu yaşadığını', 'Mannheim\'da konserlerin ayakta dinlendiğini'], 'Barok müzikte gürlük genellikle bloklar halinde değişirdi; Mannheim\'ın disiplinli ve kademeli crescendosu çağdaşlarına çarpıcı bir yenilik olarak gelmiştir.'),
  ('Haydn ile Mozart arasındaki ilişki için hangisi doğrudur?', 'Birbirine saygı duyan, birbirinden etkilenen dostlardı', ['Hiç karşılaşmamışlardır', 'Mozart, Haydn\'ın öğretmeniydi', 'Birbirlerinin eserlerinin çalınmasını yasaklattılar'], 'Mozart altı yaylı dörtlüsünü Haydn\'a ithaf etmiş, Haydn da Mozart\'ın babasına oğlunun tanıdığı en büyük besteci olduğunu söylemiştir.'),
  ('Mozart\'ın \'Don Giovanni\' operasının sonunda baş karakterin bir heykelin sesiyle cehenneme sürüklenmesi, operayı hangi türlerin karışımı yapar?', 'Komik ve trajik öğeleri birleştiren bir \'dramma giocoso\'', ['Yalnızca dinsel bir oratoryo', 'Yalnızca konuşmalı bir halk oyunu', 'Tamamen sözsüz bir bale'], 'Da Ponte ve Mozart bu eseri \'dramma giocoso\' (neşeli dram) olarak nitelemiştir; uşak Leporello\'nun mizahı ile ölüm sahnesinin korkusu yan yana yer alır.'),
  ('Beethoven\'ın notalarına ayrıntılı gürlük ve tempo işaretleri yazması, icracıyla ilişkisi hakkında ne gösterir?', 'Eserin nasıl çalınacağını daha çok kendisinin belirlemek istediğini', ['İcracıların tamamen doğaçlama yapmasını istediğini', 'Notalarını hiç yayımlamadığını', 'Eserlerinin sessiz okunmasını istediğini'], 'Beethoven\'ın dönemi, bestecinin yazdıkları ile icracının özgürlüğü arasındaki dengenin besteci lehine kaydığı bir dönemdir.'),
  ('Beethoven\'ın \'Eroica\' ithafını geri çekmesi olayı, onun hangi düşünsel bağlılığıyla birlikte değerlendirilir?', 'Fransız Devrimi\'nin özgürlük ve eşitlik idealleri', ['Mutlak monarşiye bağlılığı', 'Kilise hiyerarşisine bağlılığı', 'Barok saray geleneğine ve soylu hamilere bağlılığı'], 'Beethoven Aydınlanma ve devrim ideallerinden etkilenmişti; Napolyon\'u bu ideallerin temsilcisi sanmış, imparator olunca hayal kırıklığına uğramıştır.'),
  ('Schubert\'in yaşarken geniş bir kamu tarafından değil, daha çok dost çevresince tanınması onun kariyeri hakkında ne söyler?', 'Büyük ününün büyük ölçüde ölümünden sonra geldiğini', ['Yaşarken Avrupa\'nın en zengin bestecisi olduğunu', 'Saray bestecisi olarak çalıştığını', 'Eserlerini hiçbir zaman bitiremediğini'], 'Schubert\'in birçok büyük eseri, örneğin Do majör Senfoni, ölümünden yıllar sonra keşfedilip seslendirilmiştir.'),
  ('Bir şarkıda her kıta aynı ezgiyle söylenmek yerine, şiirin öyküsü ilerledikçe müzik de sürekli değişiyor. Schubert\'in \'Erlkönig\'inde de görülen bu yapıya ne ad verilir?', 'Baştan sona bestelenmiş (durchkomponiert) şarkı', ['Strofik şarkı', 'Da capo aryası', 'Kanon'], 'Strofik şarkıda her kıta aynı ezgiyle söylenir; baştan sona bestelenmiş şarkıda ise müzik metnin gelişimini adım adım izler.'),
  ('Clara Schumann\'ın bestecilik kariyerinin kocasının ölümünden sonra büyük ölçüde durması, 19. yüzyılda kadın müzisyenler hakkında hangi gerçeği yansıtır?', 'Kadınların bestecilikte toplumsal engellerle karşılaştığını', ['Kadınların hiç konser vermediğini', 'Kadınların salonlar dışında piyano çalmasının yasak olduğunu', 'Kadın bestecilerin eserlerinin hiç basılmadığını'], 'Clara bir dönem besteciliğe kuşkuyla yaklaşmış, yedi çocuğa bakarken geçimini daha çok konser piyanistliğiyle sağlamıştır.'),
  ('Chopin\'in büyük konser salonları yerine Paris\'teki zarif salonlarda çalmayı tercih etmesi, piyano müziği üzerinde nasıl bir etki bırakmıştır?', 'İnce nüanslı ve şiirsel bir çalış tarzını öne çıkarması', ['Yalnızca gürültülü ve gösterişli eserler yazmasına', 'Piyano yerine org çalmaya yönelmesine', 'Bestelerini orkestraya aktarmasına'], 'Chopin hayatı boyunca sınırlı sayıda kamusal konser vermiş, küçük topluluklar önünde incelikli bir çalışla tanınmıştır.'),
  ('Bir piyanist, Polonya\'nın soylu bir dans türünü temel alan, görkemli ve ağırbaşlı üçlü ölçülü bir Chopin eseri çalıyor. Bu eser büyük olasılıkla hangisidir?', 'Polonez', ['Noktürn', 'Etüt', 'Prelüd'], 'Polonez ağırbaşlı ve törensel bir Polonya dansıdır; Chopin\'in \'Kahramanlık\' polonezi bunun en ünlü örneklerindendir.'),
  ('Wagner\'in Bayreuth\'taki tiyatrosunda orkestra çukurunu seyircinin göremeyeceği biçimde örtmesi hangi amaca yönelikti?', 'Seyircinin dikkatini sahnedeki drama yoğunlaştırmak', ['Orkestrayı daha az müzisyenle ve daha ucuza çalıştırmak', 'Şarkıcıların hiç duyulmamasını sağlamak', 'Seyircinin konuşmasına izin vermek'], 'Görünmez orkestra, Wagner\'in sesin gizemli bir kaynaktan geliyormuş gibi duyulmasını ve izleyicinin kendini dramın içinde kaybetmesini istemesinin sonucuydu.'),
  ('Verdi\'nin operalarında sık görülen baba–kız ilişkisi, örneğin \'Rigoletto\'da, nasıl bir dramatik çatışma yaratır?', 'Koruma isteği ile trajik sonuç arasındaki gerilimi', ['Mizahi bir yanlış anlaşılmayı', 'Dinsel bir ayini', 'Bir dans yarışmasını ve köy şenliğini'], 'Rigoletto\'da soytarı Rigoletto\'nun kızını koruma çabası onun ölümüyle sonuçlanır; Verdi bu tür aile çatışmalarını güçlü bir dramatik malzeme olarak kullanmıştır.'),
  ('Stravinski\'nin \'Ateş Kuşu\', \'Petruşka\' ve \'Bahar Ayini\' balelerinin bestelenme sırasıyla doğru dizilişi hangisidir?', 'Ateş Kuşu → Petruşka → Bahar Ayini', ['Bahar Ayini → Ateş Kuşu → Petruşka', 'Petruşka → Bahar Ayini → Ateş Kuşu', 'Ateş Kuşu → Bahar Ayini → Petruşka'], 'Ateş Kuşu 1910\'da, Petruşka 1911\'de, Bahar Ayini 1913\'te sahnelenmiştir.'),
  ('Schoenberg\'in öğrencileri Berg ve Webern\'i karşılaştıran bir öğrencinin yazdığı ifadelerden hangisi doğrudur?', 'Berg daha lirik ve Romantik, Webern daha yoğun ve kısa eserler yazmıştır', ['Berg tamamen tonal, Webern ise yalnızca halk müziği düzenlemeleri yazmıştır', 'İkisi de yalnızca opera bestelemiştir', 'Webern operaları, Berg ise yalnızca kısa piyano parçalarıyla tanınır'], 'Berg\'in Wozzeck ve Keman Konçertosu gibi eserleri Romantik bir sıcaklık taşır; Webern ise aşırı yoğunlaştırılmış, kısa eserleriyle bilinir.'),
  ('Elgar\'ın müziğinin Edward dönemi İngiltere\'sinde (1900\'ler) çok sevilmesi, hangi toplumsal duyguyla bağlantılıdır?', 'İmparatorluk dönemi ulusal gururuyla', ['Sanayi devrimine karşı bir isyan duygusuyla', 'Sovyet devrimine duyulan sempatiyle', 'Fransız kraliyetine bağlılıkla'], 'Elgar\'ın marşları ve törensel eserleri, dönemin İngiliz ulusal kimliğinin ve imparatorluk gururunun müzikteki sesi olarak görülmüştür.'),
  ('Bernstein\'ın hem besteci hem şef hem de televizyonda gençlere müzik anlatan bir eğitimci olması, 20. yüzyılda müzisyen rolünün nasıl değiştiğini gösterir?', 'Kitle iletişim araçlarıyla geniş kitlelere ulaşan bir kamu figürüne dönüşmesi', ['Müzisyenlerin yeniden yalnızca saraylarda ve soyluların hizmetinde çalışmaya başlaması', 'Müzisyenlerin kamusal yaşamdan çekilmesi', 'Bestecilerin yalnızca kiliseler için yazması'], 'Bernstein\'ın \'Gençlik Konserleri\' programları televizyon aracılığıyla milyonlarca izleyiciye klasik müziği tanıtmıştır.'),
  ('John Cage\'in Zen Budizmi\'nden ve I Ching\'den etkilenmesi, müziğinde hangi tercihe yol açmıştır?', 'Bestecinin denetimini azaltıp rastlantıya yer açma', ['Her notayı titizlikle denetleyen bütünsel dizisellik', 'Barok füg kurallarına sıkı bağlılık', 'Romantik program müziğine dönüş'], 'Cage, bestecinin kişisel zevkini ve iradesini geri plana çekmek için şans işlemlerine başvurmuştur.'),
  ('Savaş sonrası avangart bestecilerin bir kısmının Almanya\'daki yaz kurslarında bir araya geldiği ve dizisel müziğin merkezi haline gelen kent hangisidir?', 'Darmstadt', ['Bayreuth', 'Salzburg ve Linz', 'Leipzig'], 'Darmstadt Uluslararası Yeni Müzik Yaz Kursları 1946\'da başlamış; Boulez, Stockhausen ve Nono gibi besteciler burada etkin olmuştur.'),
  ('Philip Glass\'ın film müzikleri ve operaları sayesinde geniş bir dinleyici kitlesine ulaşması, minimalizmin hangi özelliğiyle ilişkilendirilebilir?', 'Düzenli nabız ve tonal uyum nedeniyle kolay dinlenebilir olması', ['Gürültüye dayalı, tonalitesiz ve düzensiz ritimli olması', 'Yalnızca uzmanların anlayabileceği karmaşık dizilere dayanması', 'Hiçbir ritim içermemesi'], 'Minimalizmin tekrara dayalı, tonal ve ritmik yapısı, popüler müzik dinleyicilerine de tanıdık gelmiştir.'),
  ('Monteverdi\'nin madrigal kitaplarında zamanla basso continuo eşliğine ve solo seslere yer vermesi neyin göstergesidir?', 'Rönesans\'tan Barok\'a geçişin', ['Barok\'tan Klasik\'e geçişin', 'Orta Çağ\'dan Rönesans\'a geçişin', 'Romantik\'ten 20. yüzyıla geçişin'], 'Monteverdi\'nin erken madrigalleri Rönesans üslubunda, beşinci kitaptan sonrakiler ise continuo eşlikli ve Barok anlayışa uygundur.'),
  ('Josquin\'in döneminde bir bestecinin İtalya\'daki bir dük sarayında, ardından Fransız kralının yanında çalışması neyi gösterir?', 'Bestecilerin Avrupa saraylarında aranan uluslararası ustalar olduğunu', ['Bestecilerin yalnızca kendi kasabalarında çalıştığını', 'Sarayların müzisyen istihdam etmediğini ve müziği yalnızca kiliselerin desteklediğini', 'Bestecilerin yalnızca manastırlarda yaşadığını'], 'Josquin Milano, Roma, Ferrara ve Fransa\'da çalışmış; Franko-Flaman ustalar saraylar arasında el üstünde tutulan müzisyenlerdi.'),
  ('Bir müzik öğretmeni sınıfa Bach\'ın bir füğünü ve Debussy\'nin bir prelüdünü dinletiyor. Öğrencilerin fark etmesi beklenen en belirgin dokusal fark hangisidir?', 'Bach\'ta bağımsız ses çizgileri, Debussy\'de renk ve atmosfer öne çıkar', ['Bach\'ta hiç ezgi yoktur, Debussy\'de yalnızca ritim vardır', 'Bach elektronik sesler, Debussy ise yalnızca akustik çalgılar kullanır', 'İkisi arasında hiçbir fark yoktur'], 'Füg kontrpuana, yani birbirini taklit eden bağımsız seslere dayanır; Debussy ise akorları renk ve tını için kullanarak atmosferik bir doku yaratır.'),
  ('Bir konser salonunda 1900\'lerin başında seslendirilen bir eserde seyircinin protesto edip salondan çıkması, o dönemin müzik ortamı hakkında ne düşündürür?', 'Yeni ses dillerinin dinleyici beklentileriyle sert biçimde çatıştığını', ['Dinleyicilerin konser müziğine hiç ilgi duymadığını ve salonları boş bıraktığını', 'Konser salonlarının bu dönemde kapatıldığını', 'Bütün bestecilerin aynı üslupta yazdığını'], 'Bahar Ayini (1913) ve Schoenberg\'in Viyana\'daki \'Skandal Konseri\' (1913) gibi olaylar modernist müziğin yarattığı şoku gösterir.'),
  ('Bir Barok konçerto grosso dinlerken solistler grubunun sustuğu ve bütün orkestranın birlikte çaldığı bölümleri belirtmek için kullanılan terim hangisidir?', 'Tutti', ['Solo', 'Kadans', 'Rubato'], 'Tutti (\'hepsi\') bütün topluluğun birlikte çaldığı bölümleri ifade eder; concertino ise küçük solist grubudur.'),
  ('Händel\'in Messiah\'taki \'Hallelujah\' korosunu dinlerken seyircinin ayağa kalkması geleneğinin kökeni olarak anlatılan olay nedir?', 'Kral II. George\'un bu koro sırasında ayağa kalktığı rivayeti', ['Händel\'in seyirciden ayağa kalkmasını istemesi', 'Salonda oturacak yer bulunmaması ve seyircinin ayakta kalmak zorunda olması', 'Koroyu bir askerî bandonun çalması'], 'Rivayete göre Kral II. George Londra\'daki ilk seslendirmelerden birinde ayağa kalkmış, seyirci de ona uymuştur; olayın gerçekliği kesin değildir.'),
  ('Çaykovski\'nin \'Kuğu Gölü\'nün 1877\'deki ilk sahnelenişinin başarısız olması ama sonradan dünyanın en çok sahnelenen balelerinden biri haline gelmesi neyi gösterir?', 'Bir eserin ilk karşılanışının kalıcı değerini her zaman yansıtmadığını', ['Balenin hiç sahnelenmediğini', 'Çaykovski\'nin baleyi yaktığını ve yeniden yazmak zorunda kaldığını', 'Eserin bir opera olduğunu'], 'Kuğu Gölü, Petipa ve İvanov\'un 1895\'teki yeni koreografisiyle büyük başarı kazanmıştır.'),
  ('Bir öğrenci minimalist müziği \'sıkıcı tekrarlardan ibaret\' diye eleştiriyor. Bu eleştiriye verilebilecek en güçlü karşı görüş hangisidir?', 'Küçük değişimlerin uzun sürede algıyı dönüştürmesinin bilinçli bir estetik amaç olduğu', ['Minimalizmin aslında Barok füglerden oluştuğu', 'Minimalist eserlerin hiç tekrar içermediği', 'Minimalizmin yalnızca sessizlikten oluştuğu'], 'Reich ve Glass gibi besteciler, dinleyicinin yavaş değişimleri fark etmesini ve zamanı farklı algılamasını amaçlamıştır.'),
  ('Bir öğrenci Barok müziğin \'çizgisel\', Klasik müziğin ise \'dengeli cümleli\' olduğunu söylüyor. Bu ayrımı en iyi destekleyen eser çifti hangisidir?', 'Bach\'ın bir füğü ile Mozart\'ın bir sonatı', ['Debussy\'nin bir prelüdü ile Ravel\'in Bolero\'su', 'Palestrina\'nın bir missası ile Josquin\'in bir moteti', 'Cage\'in 4′33″ı ile Reich\'ın bir eseri'], 'Bach\'ın füglerinde birbirine dolanan sesler, Mozart\'ın sonatlarında ise soru–cevap biçiminde dengeli ezgi cümleleri öne çıkar.'),
  ('Liszt\'in senfonik şiirleri ile Richard Strauss\'un \'Don Juan\' ve \'Till Eulenspiegel\' eserleri arasındaki bağ nedir?', 'Strauss\'un Liszt\'in başlattığı senfonik şiir türünü geliştirmesi', ['Strauss\'un Liszt\'in yarım kalan operalarını onun ölümünden sonra tamamlaması', 'İkisinin de Barok süit olması', 'İkisinin de yalnızca piyano için yazılması'], 'Liszt\'in 1850\'lerde başlattığı senfonik şiir, Strauss\'un elinde daha ayrıntılı bir anlatım ve parlak bir orkestrasyona kavuşmuştur.'),
  ('Bir dinleyicinin \'Bu eserde ezgi yok, yalnızca birbirine yakın yüzlerce ses aynı anda titreşiyor ve bir bulut gibi yavaşça değişiyor\' dediği eser hangisi olabilir?', 'Ligeti – Atmosphères', ['Mozart – Sihirli Flüt', 'Verdi – Aida', 'Chopin – Polonez'], 'Ligeti\'nin \'mikropolifoni\' adını verdiği bu yazıda tek tek sesler duyulmaz; dinleyici yoğun ve yavaşça değişen bir ses bulutu algılar.'),
  ('Gluck\'un opera reformu ile Wagner\'in müzikli dram anlayışı arasında hangi benzerlik vardır?', 'İkisi de müziğin dramaya hizmet etmesini savunmuştur', ['İkisi de yalnızca komik opera yazmıştır', 'İkisi de aynı yüzyılda yaşamıştır', 'İkisi de operanın tamamen konuşmalı olmasını istemiştir'], 'Gluck 18. yüzyılda, Wagner 19. yüzyılda, şarkıcı gösterilerinin değil dramanın operada belirleyici olması gerektiğini savunmuştur.'),
  ('13. yüzyıl İngiltere\'sinden kalan ve bilinen en eski çok sesli \'rota\' (kanon) örneği sayılan eser hangisidir?', 'Sumer is icumen in', ['Greensleeves türküsü', 'Ein feste Burg ist unser Gott', 'L\'homme armé şarkısı'], '\'Yaz geldi\' anlamına gelen bu İngilizce şarkı, seslerin aynı ezgiyle sırayla girdiği bir kanondur ve 13. yüzyıla tarihlenir.'),
  ('Barok döneminde kastrato şarkıcıların opera sahnesinde bu kadar aranmasının bir nedeni olarak hangisi gösterilebilir?', 'Kadınların bazı yerlerde, örneğin Papalık Roma\'sında, sahneye çıkamaması', ['Kastratoların yalnızca bas partileri söyleyebilmesi', 'Operaların hep komik konular işlemesi', 'Erkeklerin şarkı söylemesinin yasaklanması'], 'Kilisede ve bazı sahnelerde kadınlara izin verilmemesi, yüksek ve güçlü sesli kastratoları vazgeçilmez kılmıştı.'),
  ('Bach\'ın uykusuzluk çeken bir kont için yazdığı söylenen ve bir arya ile otuz varyasyondan oluşan klavye eseri hangisidir?', 'Goldberg Varyasyonları', ['İtalyan Konçertosu', 'Füg Sanatı', 'Fransız Süitleri'], 'Bach\'ın biyografi yazarı Forkel\'e göre eser, Kont Keyserlingk\'in klavsencisi Goldberg\'in geceleri çalması için yazılmıştır; öykünün doğruluğu tartışmalıdır.'),
  ('Bach\'ın org eserlerinin kiliselerde çalınmak üzere yazılmış olması, bu eserlerin işlevi hakkında ne söyler?', 'Ayini başlatma, cemaate eşlik etme ve koralı tanıtma görevleri üstlendiklerini', ['Yalnızca konser salonlarında çalındıklarını', 'Dans eşliği olarak kullanıldıklarını', 'Opera sahnelerinde perde arası müziği olduklarını'], 'Bach\'ın koral prelüdleri cemaatin söyleyeceği ezgiyi tanıtır; prelüd ve fügler ise ayin öncesi ve sonrasında çalınırdı.'),
  ('Antonio Salieri\'nin Mozart\'ı zehirlediği iddiası bugün nasıl değerlendirilir?', 'Kanıtı olmayan, edebiyat ve sinemanın yaydığı bir efsane olarak', ['Mahkeme kararıyla kanıtlanmış bir olay olarak', 'Mozart\'ın mektuplarında anlattığı bir gerçek olarak', 'Salieri\'nin itiraf ettiği belgelenmiş bir suç olarak'], 'Söylenti Puşkin\'in kısa oyunu ve \'Amadeus\' filmiyle yaygınlaşmıştır; tarihçiler bunu destekleyen bir kanıt bulamamıştır.'),
  ('Mozart\'ın çağdaşı Antonio Salieri\'nin müzik tarihindeki gerçek rolü için hangisi doğrudur?', 'Saygın bir saray bestecisi ve Beethoven, Schubert, Liszt\'in öğretmeni', ['Hiç eser yazmamış bir saray hizmetkârıydı', 'Mozart\'ın babasıydı', 'Yalnızca Paris\'te çalışmış bir kemancıydı'], 'Salieri Viyana saray kapel ustasıydı ve opera besteciliğinin yanı sıra Beethoven, Schubert ve genç Liszt\'e ders vermiştir.'),
  ('Beethoven\'ın 5. Piyano Konçertosu\'nun \'İmparator\' adı için hangisi doğrudur?', 'Ad Beethoven\'a değil, sonradan başkalarına aittir', ['Eser Napolyon\'a ithaf edildiği için bu adı almıştır', 'Beethoven bu adı imparatorun isteğiyle koymuştur', 'Eser bir imparatorun taç giyme töreni için yazılmıştır'], 'Ayışığı Sonatı gibi \'İmparator\' adı da besteciye ait değildir; büyük olasılıkla eserin görkemli karakteri nedeniyle İngiltere\'de yaygınlaşmıştır.'),
  ('Carl Maria von Weber\'in 1821\'de Berlin\'de sahnelenen ve Alman romantik operasının ilk büyük başarılarından sayılan eseri hangisidir?', 'Der Freischütz', ['Fidelio', 'Lohengrin', 'Die Zauberflöte'], 'Der Freischütz Alman ormanı, halk ezgileri ve doğaüstü \'Kurtlar Vadisi\' sahnesiyle Alman ulusal operasının simgesi olmuştur.'),
  ('Kurt Weill ile Bertolt Brecht\'in 1928\'de sahnelenen \'Üç Kuruşluk Opera\'sı hangi 18. yüzyıl eserinin modern bir uyarlamasıdır?', 'Dilenci Operası (The Beggar\'s Opera)', ['Sihirli Flüt', 'Dido ve Aeneas', 'Sevil Berberi (Rossini\'nin operası)'], 'Weill ve Brecht, John Gay\'in 1728 tarihli eserini Berlin\'in kabare ve caz havasıyla toplumsal bir hicve dönüştürmüştür; \'Bıçak Mack\' şarkısı buradan çıkmıştır.'),
  ('John Gay\'in \'Dilenci Operası\' ile Weill–Brecht\'in \'Üç Kuruşluk Opera\'sı arasındaki ortak tavır nedir?', 'Popüler şarkılar ve alt sınıf karakterlerle toplumu hicvetmek', ['Antik mitolojiyi yüceltmek', 'Yalnızca kilise müziğini kullanmak', 'Kraliyet ailesini övmek'], 'İki eser de hırsızları ve dilencileri sahneye taşıyarak dönemlerinin ikiyüzlülüğünü ve ciddi operanın kalıplarını alaya almıştır.'),
  ('Brezilyalı besteci Heitor Villa-Lobos\'un \'Bachianas Brasileiras\' adlı eserleri hangi iki kaynağı birleştirir?', 'Bach\'ın kontrpuan üslubu ile Brezilya halk müziği', ['Gregoryen ilahi ile elektronik müzik', 'Viyana valsi ile Japon saray müziği ve gagaku', 'İtalyan operası ile Rus kilise müziği'], 'Villa-Lobos, Bach\'a duyduğu hayranlığı Brezilya\'nın halk ezgi ve ritimleriyle birleştiren dokuz eserlik bir dizi yazmıştır.'),
  ('Fransız müzik eğitimci Nadia Boulanger\'in 20. yüzyıl müziğindeki önemi en çok hangi yönüyle açıklanır?', 'Copland ve Glass gibi birçok besteciyi yetiştirmesiyle', ['Bilinen ilk operayı yazmasıyla', 'Piyanoyu icat etmesiyle', 'Gregoryen ilahileri derlemesiyle'], 'Nadia Boulanger Paris ve Fontainebleau\'da onlarca yıl kompozisyon öğretmiş; Aaron Copland, Philip Glass ve Astor Piazzolla öğrencileri arasındadır.'),
  ('19. yüzyılın sonunda ses kaydının icadı, sonraki müzik tarihçileri için hangi yeni olanağı sağlamıştır?', 'Eserlerin nasıl çalındığını doğrudan duyabilmeyi', ['Orta Çağ ilahilerinin özgün seslerini dinleyebilmeyi', 'Bach\'ın kendi çalışını dinleyebilmeyi', 'Nota yazısını gereksiz kılmayı'], 'Kayıtlar, Rahmaninov ya da Elgar gibi bestecilerin kendi eserlerini nasıl çaldığını ya da yönettiğini belgeleyerek yorum tarihinin incelenmesini sağlamıştır.'),
  ('Bir öğrenci, bestecinin eserine müzik dışı bir başlık verip vermemesinin dinleyiciyi nasıl etkilediğini tartışıyor. Aşağıdaki örneklerden hangisi başlığı besteciye ait olmayan bir esere örnektir?', 'Beethoven\'ın \'Ay Işığı\' Sonatı', ['Berlioz\'un \'Fantastik Senfoni\'si', 'Vivaldi\'nin \'Dört Mevsim\'i', 'Smetana\'nın \'Moldau\'su'], 'Ay Işığı adı Beethoven\'ın ölümünden sonra verilmiştir; diğer eserlerin başlıklarını besteciler kendileri koymuştur.'),
  ('Bir öğrenci \'Romantik besteciler Klasik biçimleri tamamen terk etti\' diyor. Bu genellemeye karşı en güçlü örnek hangisidir?', 'Brahms\'ın senfonilerinde sonat biçimini sürdürmesi', ['Liszt\'in senfonik şiirleri', 'Berlioz\'un Fantastik Senfonisi', 'Wagner\'in müzikli dramları ve leitmotiv tekniği'], 'Brahms Romantik bir besteci olduğu halde senfoni, konçerto ve oda müziğinde Klasik biçimlere bağlı kalmıştır; diğer örnekler biçimsel yeniliklere işaret eder.'),
];
